COLLDATA("musnadshafiiur","ur",[[1603,"اسامہ بن زید رضی اللہ عنہ سے روایت ہے فرمایا، عبداللہ بن ابی کی تین منافقانہ مجلسوں میں میں موجود تھا۔ (1)","",{"k":"(1) اسنادہ ضعیف لانقطاعہ بین الزہری وأسامة: البیہقی (8/198)، المعرفة السنن والآثار لہ (5028)۔"}],[1604,"ثابت بن ضحاک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے دنیا میں کسی چیز سے خود کشی کر لی، قیامت کے دن اسے اسی چیز سے عذاب ہوگا۔‘‘ (1)","",{"k":"(1) البخاری (6652)، مسلم (110)۔","f":"۱۔ خود کشی حرام ہے۔\n۲۔ خود کشی کرنے والا جس چیز سے خود کشی کرے گا روز قیامت اسے اسی چیز سے عذاب دیا جائے گا۔\n۳۔ نبی صلی اللہ علیہ وسلم نے خود کشی کرنے والے انسان کی نماز جنازہ نہیں پڑھائی۔ (دیکھیے: صحیح مسلم، رقم: ۹۷۸)"}],[1605,"عثمان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تین چیزوں میں سے کسی ایک کے ساتھ مسلمان کا قتل جائز ہوتا ہے۔ ایمان لانے کے بعد کافر مرتد ہو جانا، شادی شدہ ہوتے ہوئے زنا کرنا یا کسی کو ناحق قتل کرنا۔‘‘ (1)","",{"k":"(1) صحیح من غیر ہذا الطریق: ابوداود (4502)، الترمذی (2158)، وقال ’’حسن‘‘، النسائی (4024)، ابن ماجة (2533)، وصححہ ابن الجارود (836)، الحاکم (4/350)۔","f":"۱۔ معلوم ہوا حدیث میں مذکور تین اسباب کے علاوہ ہر قتل غیر مشروع اور ناحق ہے۔\n۲۔ اسلام ترک کر کے کسی دوسرے مذہب کو اختیار کرنا ارتداد کہلاتا ہے اور مرتد واجب القتل ہے۔\n۳۔ شادی شدہ زانی کو پتھر مار مار کر سنگسار کیا جائے گا۔\n۴۔ کسی مسلمان کو ناحق قتل کرنا سنگین جرم ہے اور اس کی اخروی سزا ابدی جہنم ہے۔\n۵۔ حدیث میں مذکور سزائیں عام لوگ نہیں دیں گے بلکہ ان شرعی سزاؤں کا نفاذ قاضی کے ذریعے ہوگا۔"}],[1606,"عثمان بن عفان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تین چیزوں میں سے کسی ایک سے مسلمان آدمی کا خون جائز ہوتا ہے، ایمان کے بعد مرتد ہو جانا یا شادی شدہ ہونے کے بعد زنا کرنا یا کسی جان کو ناحق قتل کرنا۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1065)"}],[1607,"زید بن اسلم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے اپنے دین (اسلام) کو بدل دیا اس کی گردن کو مار دو۔‘‘ (1)","",{"k":"(1) صحیح من غیر ہذا الطریق من حدیث ابن عباس: البخاری (3017، 6922)۔","f":"۱۔ دین تبدیل کرنے سے مراد اسلام کو چھوڑ کر عیسائیت یا یہودیت وغیرہ کا اختیار کرنا ہے اور ایسا کرنے والے مرتد کی سزا قتل ہے خواہ وہ مرد ہو یا عورت۔\n۲۔ مرتد کے لیے توبہ کی گنجائش موجود ہے۔ اگر وہ توبہ کر کے خلوص دل سے اسلام قبول کر لے بہتر ہے ورنہ اسے قتل کر دیا جائے گا۔ سیدنا ابو موسیٰ اشعری رضی اللہ عنہ بیان فرماتے ہیں: ’’قدم علی معاذ، وانا بالیمن ورجل کان یہودیا فاسلم فارتدّ عن الاسلام فلما قدم معاذ؛ قال: لا انزل عن دابتی حتى يقتل فقتل، قال احدهما وکان قد استتیب قبل ذلک’’‘‘میں یمن میں عامل (گورنر) تھا کہ میرے پاس سیدنا معاذ رضی اللہ عنہ تشریف لائے اور ایک یہودی جس نے اسلام قبول کیا پھر مرتد ہو گیا، جب سیدنا معاذ رضی اللہ عنہ تشریف لائے تو انہوں نے کہا میں اپنی سواری سے اس وقت تک نہیں اتروں گا جب تک کہ اسے قتل نہ کر دیا جائے، پھر اسے قتل کر دیا گیا۔ دونوں (طلحہ اور بریدہ راویوں) میں سے ایک نے کہا اس شخص کو اس سے پہلے توبہ کر لینے کا کہا گیا تھا۔‘‘ (سنن ابو داود، کتاب الحدود، باب الحکم فیمن ارتد، رقم: ۴۳۵۵)\n۳۔ عبداللہ بن سعد بن ابو سرح رضی اللہ عنہ نے اسلام قبول کیا تو رسول اللہ صلی اللہ علیہ وسلم کے کاتب رہے پھر مرتد ہو گئے، جب مکہ فتح ہوا تو سیدنا عثمان بن عفان رضی اللہ عنہ کی سفارش سے ان کی توبہ قبول کر لی گئی۔ (سنن ابو داود، رقم: ۴۳۵۹)\n۴۔ اگر کوئی جبر و اکراہ کی وجہ سے اسلام سے برأت کا اظہار کرے جبکہ وہ دلی طور پر پکا و سچا مسلمان ہو تو اس پر مرتد کا حکم نہیں لگے گا۔ بلکہ کافر ہونے کے لیے کفر پر شرح صدر ضروری ہے۔ ارشادِ باری تعالیٰ ہے: ﴿مَنْ كَفَرَ بِاللهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ﴾ (النحل: ۱۰۶) ’’جس نے اپنے ایمان کے بعد اللہ سے کفر کیا سوائے اس کے جسے مجبور کر دیا گیا اور اس کا دل ایمان پر مطمئن رہا۔‘‘"}],[1608,"محمد بن عبداللہ بن عبدالقاری سے روایت ہے انہوں نے فرمایا کہ عمر بن خطاب رضی اللہ عنہ کے پاس ابو موسیٰ (اشعری) رضی اللہ عنہ کے پاس سے ایک آدمی آیا تو عمر رضی اللہ عنہ نے اس سے وہاں کے لوگوں کا حال پوچھا تو اس نے بتایا پھر پوچھا، کیا کوئی نئی خبر ہے جو تمہارے دور کے شہر سے متعلق ہو؟ تو اس آدمی نے کہا، ہاں۔ ایک آدمی اسلام لانے کے بعد مرتد ہو گیا، عمر رضی اللہ عنہ نے کہا، تم نے اس کے ساتھ کیا کیا؟ اس نے کہا، ہم نے اسے پکڑا اور اس کی گردن مار دی، تو عمر رضی اللہ عنہ نے فرمایا، تم نے اسے تین دن تک قید کیوں نہ کیا، اور تم اسے ہر روز روٹی دیتے اور اس سے توبہ کرواتے، شاید وہ توبہ کرتا اور اللہ کا حکم مان لیتا، (پھر عمر رضی اللہ عنہ نے فرمایا) اے اللہ! نہ میں وہاں موجود تھا، نہ میں اس خبر سے خوش ہوں اور نہ میں نے حکم دیا جبکہ مجھے معلوم ہوا۔ (1)","",{"k":"(1) اسنادہ ضعیف: البیہقی (8/206، 207)، المعرفة السنن والآثار لہ (5032)، الطحاوی فی شرح المعانی (3/211)۔"}],[1609,"سعید بن زید بن عمرو بن نفیل سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو اپنے مال کی حفاظت کرتے ہوئے قتل کیا گیا وہ شہید ہے۔‘‘ (1)","",{"k":"(1) اخرجہ ابوداود (4772)۔ والترمذی (1421) وقال ’’حسن صحیح‘‘۔ وابن ماجة (2580)۔ والنسائی (4099)، (4100)۔ وصححہ ابن حبان."}],[1610,"سعید بن زید بن عمرو بن نفیل سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اور جو اپنے مال کی حفاظت کرتے ہوئے مارا جائے وہ شہید ہے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1609)","f":"۱۔ ہر شخص کو چاہیے کہ اپنی جان، مال، عزت و آبرو کی حفاظت کرے۔\n۲۔ جان و مال اور عزت و آبرو کی حفاظت کرتے ہوئے دفاع کرنے والا اگر قتل ہو جائے تو وہ شہید ہے تاہم اس کا درجہ اسلامی حدود کی حفاظت اور اعلائے کلمة اللہ کے لیے میدانِ جنگ میں لڑنے والے سے کم ہے لہذا اسے غسل و کفن کے بعد دفن کیا جائے گا۔\n۳۔ چورا چاکوں اور ڈاکوؤں سے لڑنا اور اپنا دفاع کرنا جائز ہے۔"}],[1611,"سعید بن مسیب رضی اللہ عنہ سے روایت ہے کہ عمر رضی اللہ عنہ نے پانچ یا سات آدمی کو ایک آدمی کے بدلے میں قتل کیا، جسے انہوں نے دھوکے سے مارا تھا، اور عمر رضی اللہ عنہ نے فرمایا: اگر صنعاء (یمن کا ایک مشہور شہر) کے تمام لوگ اس قتل میں شریک ہوتے تو میں تمام کو قصاص میں قتل کر دیتا۔ (1)","",{"k":"(1) صحیح: البیہقی (8/40، 41)، المعرفة السنن والآثار لہ (4831)، عبدالرزاق (18073، 18075)، ابن ابی شیبة (27684، 27685)۔","f":"معلوم ہوا اگر ایک جماعت ایک آدمی کے قتل میں شریک ہو تو جماعت کے تمام افراد کو قتل کر دیا جائے گا۔"}],[1612,"عمرو بن دینار رضی اللہ عنہ سے روایت ہے انہوں نے بجالہ رضی اللہ عنہ سے سنا وہ فرماتے ہیں کہ عمر رضی اللہ عنہ نے (اپنے گورنروں کے نام) لکھا کہ ہر جادوگر اور جادوگرنی کو قتل کر دو، بجالہ نے کہا، پھر ہم نے تین جادوگرنیوں کو قتل کیا۔ (1)","",{"k":"(1) ابوداود (3043)، احمد (1/190، 191)، وصححہ ابن الجارود (1105)۔","f":"جادو کفر ہے اور اس کا فاعل مرتد کے حکم میں ہے اور اس کی سزا بھی مرتد ہی کی سزا ہے۔ ارشادِ باری تعالیٰ ہے: ﴿وَمَا كَفَرَ سُلَيْمَنُ وَلَكِنَّ الشَّيْطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ﴾ (البقرة: ۱۰۲) ’’اور سلیمان علیہ السلام نے کفر نہیں کیا بلکہ شیطانوں نے کفر کیا وہ لوگوں کو جادو سکھاتے تھے۔‘‘"}],[1613,"فرمایا اور ہمیں بتایا گیا ہے کہ اُم المومنین سیدہ حفصہ رضی اللہ عنہا نے اپنی ایک لونڈی کو قتل کیا جس نے ان پر جادو کیا تھا۔ (1)","",{"k":"(1) صحیح: البیہقی (8/136)، المعرفة السنن والآثار لہ (4996)، عبدالرزاق (18748، 18757)۔"}],[1614,"عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے عائشہ! کیا تمہیں معلوم ہے کہ میں نے جس کام کے بارے میں رہنمائی طلب کی تھی اللہ نے اس کے بارے میں میری رہنمائی فرما دی۔ رسول اللہ صلی اللہ علیہ وسلم کی کافی مدت یہی حالت رہی کہ آپ صلی اللہ علیہ وسلم کو خیال ہوتا کہ آپ صلی اللہ علیہ وسلم نے اپنی ازواج میں سے کسی سے ہم بستری کی ہے حالانکہ آپ نے ہم بستری نہ کی ہوتی۔ میرے پاس دو آدمی (فرشتے) آئے، ایک میرے پاؤں کے پاس اور دوسرا میرے سر کے پاس (کھڑا ہو گیا)۔ میرے پاؤں کے پاس کھڑے نے سر کے پاس کھڑے سے کہا، اس آدمی کا کیا حال ہے؟ دوسرے نے کہا، اس پر جادو کر دیا گیا ہے۔ اس نے پوچھا، کس نے اس پر جادو کیا ہے؟ اس نے جواب دیا، لبید بن اعصم (یہودی) نے، اس نے پھر پوچھا، کس چیز میں اس پر جادو کیا ہے؟ اس نے کہا کنگھی میں اور کنگھی کے ساتھ سر سے اترے ہوئے بالوں میں، نر کھجور کے خوشے کے اندر جو ذروان کنویں میں رکھا ہوا ہے۔ راوی نے کہا پھر اس کو رسول اللہ صلی اللہ علیہ وسلم نے نکال لائے اور فرمایا: ’’یہ وہی ہے جو مجھے خواب میں دکھایا گیا گویا اس کے کھجور کے درخت شیطانوں کے سروں کی مانند تھے، اور اس کا پانی مہندی کے عرق جیسا (رنگین) تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کو نکالنے کا حکم دیا اور وہ اس سے نکالا۔ عائشہ رضی اللہ عنہا فرماتی ہیں، میں نے کہا اے اللہ کے رسول صلی اللہ علیہ وسلم! پس کیوں نہیں۔ سفیان نے کہا یعنی آپ نے جادو کا توڑ کیا۔ عائشہ رضی اللہ عنہا نے فرمایا، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ”اب اللہ نے مجھے شفا دی ہے، اور میں ناپسند کرتا ہوں کہ اس کی وجہ سے لوگوں میں شر پھیلاؤں۔‘‘ فرمایا: لبید بن اعصم بنی زریق کا ایک آدمی تھا جو یہودیوں کے حلیف تھے۔ (1)","",{"k":"(1) البخاری (5768)، مسلم (2189)۔","f":"۱۔ جادو شیطانی عمل ہے اور اس کی تاثیر اللہ کی مشیت سے موجود ہے۔ ارشادِ باری تعالیٰ ہے: ﴿فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَ مَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللهِ﴾ (البقرة: ۱۰۲) ’’اور لوگ ان سے وہ سیکھتے جس سے وہ خاوند و بیوی میں جدائی ڈال دیں اور وہ اللہ کی مرضی کے بغیر کسی کو کوئی نقصان نہیں پہنچا سکتے۔‘‘\n۲۔ رسول اللہ صلی اللہ علیہ وسلم پر جادو کا اثر ہو جانا منصب نبوت کے منافی نہیں ہے۔ موسیٰ علیہ السلام کے سامنے جب جادوگروں نے رسیاں پھینکی تو وہ بھی ان کے جادو کی وجہ سے انہیں سانپ سمجھنے لگے اور خوفزدہ ہو گئے۔ (دیکھیے: سورہ طہ: ۲۲، ۲۷)\n۳۔ بعض لوگ اس حدیث کا انکار کرتے ہوئے کہتے ہیں کہ اگر اس بات کو تسلیم کر لیا جائے کہ نبی صلی اللہ علیہ وسلم پر جادو ہوا تو پھر کفار کا یہ اعتراض درست ہو گا کہ ارشادِ باری تعالیٰ ہے: ﴿وَقَالَ الظَّالِمُونَ إِنْ تَتَّبِعُونَ إِلَّا رَجُلًا مَسْحُورًا﴾ (الفرقان: ۸) ’’اور ظالموں نے کہا تم تو ایسے آدمی کے پیروکار ہو جس پر جادو کیا گیا ہے۔‘‘ حالانکہ اس اعتراض کی کوئی حیثیت نہیں کیونکہ کفار قرآن، نبی صلی اللہ علیہ وسلم کی دعوت اور اس کے نتیجہ میں ملنے والی کامیابیوں کو جادو کا اثر قرار دیتے تھے۔\n۴۔ رسول اللہ صلی اللہ علیہ وسلم مشکل کشا یا عالم الغیب نہیں ہیں۔\n۵۔ یہودی شروع سے ہی اسلام، اہل اسلام اور داعی اسلام صلی اللہ علیہ وسلم کے دشمن رہے ہیں۔\n۶۔ جادو کرنا، کروانا، سیکھنا، سیکھانا سب کفریہ کام ہیں۔ مزید دیکھئے فوائد حدیث نمبر: ۱۶۱۲۔ جعلی پیروں کے پاس جانے کی بجائے کتاب وسنت کا مطالعہ کرے اور ان پر عمل کرے، ذکر و اذکار اور تلاوت کلام پاک کو معمول بنائے۔ ہر قسم کے گناہ سے بچنے کی کوشش کرے ان شاء اللہ، اللہ رب العزت شفا عطا فرمائیں گے۔"}],[1615,"عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے چڑیا یا اس سے بھی ہلکی چیز کو ناحق قتل کیا تو اللہ تعالیٰ اس سے اس کے قتل کے بارے میں پوچھیں گے۔ پوچھا گیا اے اللہ کے رسول صلی اللہ علیہ وسلم! اس کا حق کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اسے ذبح کرے پھر اسے کھائے اور اس کا سر نہ کاٹے کہ پھر اس سے نشان بازی کرے۔‘‘ (1)","",{"k":"(1) النسائی (4354، 4450)، احمد (2/166، 197)، وصححہ الحاکم (4/233)۔"}],[1616,"عکرمہ رحمہ اللہ نے بیان فرمایا کہ جب ابن عباس رضی اللہ عنہما کو یہ خبر پہنچی کہ علی رضی اللہ عنہ نے مرد اور بے دین لوگوں کو جلا دیا ہے، تو فرمایا اگر میں (ان کی جگہ) ہوتا تو میں ان کو نہ جلواتا البتہ میں ان کو قتل کر دیتا، کیونکہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے: ’’جو اپنا دین (اسلام) بدل ڈالے اس کو قتل کر دو۔’’اور میں انہیں نہ جلاتا کیونکہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے:‘‘کسی آدمی کے لیے جائز نہیں کہ وہ اللہ کے عذاب سے کسی کو عذاب دے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1607)","f":"۱۔ آگ سے عذاب دینا اللہ رب العزت کے لیے خاص ہے لہذا حاکم و قاضی یا امیر کے لیے درست نہیں کہ مجرموں کو آگ میں جلائے۔ ۲۔ ارتداد بغاوت ہے اور بغاوت نا قابل معافی جرم ہے اور جو دین اسلام سے بغاوت اختیار کرے گا اسے قتل کیا جائے گا مزید دیکھئے فوائد حدیث نمبر: ۱۶۰۷۔"}],[1617,"جعفر بن محمد نے اپنے باپ سے روایت کیا کہ علی رضی اللہ عنہ نے ابن ملجم کے متعلق فرمایا جب اس نے ان کو زخمی کیا، کہ اس کو کھلاؤ پلاؤ اور اچھے طریقے سے قید کر کے رکھو، اگر میں زندہ رہا تو میں اپنے خون کا ولی ہوں، اگر چاہوں تو معاف کر دوں، اور اگر چاہوں تو انتقام لے لوں، اور اگر میں شہید ہو جاؤں تو تم اس کو قتل کر دینا اس کا مثلہ نہ کرنا۔ (1)","",{"k":"(1) اسنادہ ضعیف لضعف شیخ الشافعی ولانقطاعہ بین محمد بن علی وعلی بن ابی طالب: البیہقی (8/183)، المعرفة السنن والآثار لہ (5003)۔"}],[1618,"جعفر بن محمد نے اپنے باپ سے ان کے دادا سے روایت کیا، فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کے قبضہ کے ساتھ ایک کتاب پائی گئی کہ ’’بے شک لوگوں میں سے اللہ سبحانہ و تعالیٰ کے ہاں سب سے بڑا ظالم وہ قاتل ہے جو لڑائی نہ کرنے والے کو قتل کرے، اور اس کو مارنے والے کے علاوہ کسی دوسرے کو مارے، اور جس نے اپنے مالکوں کے علاوہ کسی اور کو اپنا ولی بنایا تو اس نے اس وحی کا انکار کیا جو اللہ تعالیٰ نے محمد صلی اللہ علیہ وسلم پر نازل فرمائی۔‘‘ (1)","",{"k":"(1) اسنادہ ضعیف لضعف شیخ الشافعی ولانقطاعہ: البیہقی (8/26)، المعرفة السنن والآثار لہ (4797)، عبدالرزاق (18847)، ابو یعلی (330)۔"}],[1619,"محمد بن اسحاق نے روایت کیا کہ میں نے ابو جعفر محمد بن علی سے پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کی میان میں موجود صحیفے میں کیا تھا، تو انہوں نے فرمایا، اس میں تھا کہ اللہ نے اپنے قاتل کے علاوہ دوسرے کو قتل کرنے والے پر لعنت کی ہے، اور اس کو مارنے والے کے علاوہ دوسرے کو مارنے والے پر بھی (لعنت کی ہے۔) اور جس نے کسی کو کسی کی نعمت کا غیر ولی کو مالک بنا دیا اس نے اس وحی کا انکار کیا جو اللہ تعالیٰ نے محمد صلی اللہ علیہ وسلم پر نازل کی ہے۔ (1)","",{"k":"(1) اسنادہ ضعیف لإعضالہ: البیہقی (8/26)، المعرفة السنن والآثار لہ (4798)۔"}],[1620,"عمرو بن اوس سے روایت ہے فرمایا: پہلے ایک آدمی کو دوسرے کے گناہ کی وجہ سے پکڑ لیا جاتا تھا حتی کہ ابراہیم علیہ السلام آئے تو اللہ تعالیٰ نے فرمایا: اور وفادار ابراہیم علیہ السلام کے صحیفوں میں تھا، کہ کوئی شخص کسی دوسرے کا بوجھ نہیں اٹھائے گا۔“ (النجم: ۳۷، ۳۸) (1)","",{"k":"(1) اسنادہ ضعیف لارسالہ: البیہقی (8/345)، المعرفة السنن والآثار لہ (5299)۔"}],[1621,"ابو رمثہ سے روایت ہے فرمایا میں اپنے باپ کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے ہاں تشریف لے گیا، تو میرے باپ نے رسول اللہ صلی اللہ علیہ وسلم کی کمر پر کوئی چیز دیکھی، اور فرمایا: مجھے اجازت دیں میں آپ کی کمر پر موجود چیز کا علاج کروں کیونکہ میں طبیب ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تو اچھا ساتھی ہے۔’’اور رسول اللہ صلی اللہ علیہ وسلم نے دریافت کیا:‘‘یہ تیرے ساتھ کون ہے؟’’تو فرمایا، میرا بیٹا میں اس کی گواہی دیتا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘خبر دار تیرے بیٹے کے قصور کا تجھ سے اور تیرے قصور کا تیرے بیٹے سے مواخذہ نہ ہوگا۔‘‘ (1)","",{"k":"(1) ابو داود (4495)، النسائی (4836)، وصححہ ابن الجارود (770)، الحاکم (2/425)، وابن حبان۔","f":"۱۔ جرم کی سزا صرف مجرم کو ملنی چاہیے نہ کہ اس کے عزیز و اقارب کو۔ کیونکہ اللہ تعالیٰ کا قاعدہ و قانون ہے: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾ (بنی اسرائیل: ۱۵) ’’کوئی جان کسی دوسری جان کا بوجھ نہیں اٹھائے گی۔‘‘ لہذا پولیس والوں کا مفرور ملزم یا مجرم کے باپ، بیٹے یا دیگر عزیز و اقارب کو پکڑنا اور انہیں تنگ کرنا غیر اخلاقی، غیر قانونی اور غیر شرعی ہے۔ ۲۔ حدود اللہ اصل مجرم پر ہی نافذ کی جائیں گی ایسا نہیں ہوگا کہ قاتل باپ کی جگہ بطور قصاص بیٹے کو یا بیٹے کی جگہ باپ کو قتل کر دیا جائے۔"}],[1622,"عبدالرحمن بن بیلیمانی سے روایت ہے کہ مسلمانوں میں سے ایک آدمی نے ذمیوں میں سے ایک آدمی کو قتل کر دیا، جب یہ معاملہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے پیش کیا گیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’میں اپنے ذمہ کو پورا کرنے کا سب سے زیادہ حقدار ہوں۔‘‘ پھر آپ صلی اللہ علیہ وسلم نے اس کے متعلق حکم دیا اور وہ (قصاصاً) قتل کر دیا گیا۔ (1)","",{"k":"(1) اسنادہ ضعیف جدًا، فان ابراہیم بن محمد متروک وعبدالرحمن بن البیلمانی ضعیف وہو مرسل: البیہقی (8/30، 31)، المعرفة السنن والآثار لہ (4814)، عبدالرزاق (18514)، ابن ابی شیبة (27460)۔"}],[1623,"ابو الجنوب اسدی نے بیان فرمایا کہ علی رضی اللہ عنہ کے پاس مسلمانوں میں سے ایک آدمی لایا گیا جس نے ذمیوں میں سے ایک آدمی کو قتل کیا تھا۔ جب اس کے اوپر گواہی قائم ہوگئی تو آپ نے اس کے قتل کا حکم دیا تو مقتول کا بھائی آگیا اور اس نے کہا، میں نے اسے معاف کر دیا۔ تو علی رضی اللہ عنہ نے فرمایا: شاید انہوں نے تجھے ڈرایا، دھمکایا ہے یا تجھے پریشان کیا ہے۔ اس نے کہا، نہیں، لیکن اس کو قتل کر دینے سے میرا بھائی تو واپس نہیں آئے گا، انہوں نے مجھے دیت دے دی اور میں راضی ہوگیا، فرمایا تو بہتر جانتا ہے، ہاں جس کی ہم پر ذمہ داری ہے اس کا خون ہمارے خون کی مانند اور اس کی دیت ہماری دیت کی طرح ہے۔ (1)","",{"k":"(1) اسنادہ ضعیف، لجہالة الحسن بن میمون ولضعف ابی الجنوب: البیہقی (8/34)، المعرفة السنن والآثار لہ (4817)، الدارقطنی (3/147، 148)۔"}],[1624,"مجاہد اور حسن سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ والے دن فرمایا: ’’مومن کو کافر کے بدلے میں قتل نہیں کیا جائے گا۔‘‘ (1)","",{"k":"(1) اسنادہ ضعیف لارسالہ ولضعف مسلم بن خالد: البیہقی (8/29)، المعرفة السنن والآثار لہ (4981، 4983)، عبدالرزاق (18506)، ابن ابی شیبة (27473)۔"}],[1625,"ابو جحیفہ سے روایت ہے فرمایا، میں نے علی رضی اللہ عنہ سے پوچھا کیا تمہارے پاس رسول اللہ صلی اللہ علیہ وسلم کی طرف سے کوئی چیز قرآن کے علاوہ ہے؟ تو آپ نے فرمایا: اس ذات کی قسم! جس نے دانے سے کونپل کو نکالا اور مخلوق کو پیدا کیا، ہمارے پاس کچھ نہیں۔ سوائے اس فہم کے جو اللہ تعالیٰ کسی بندے کو اپنی کتاب میں دے دے اور جو کچھ اس صحیفہ میں ہے۔ میں نے پوچھا اس صحیفہ میں کیا ہے؟ فرمایا: ’’دیت کے احکام، قیدیوں کو چھڑوانے کے احکام اور یہ کہ کسی مسلمان کو کافر کے بدلے میں قتل نہ کیا جائے گا۔ دوسری جگہ میں ہے کہ کسی مومن کو کافر کے بدلے قتل نہیں کیا جائے گا۔‘‘ (1)","",{"k":"(1) البخاری (6915)۔"}],[1626,"ابو جحیفہ نے بیان فرمایا کہ میں نے علی رضی اللہ عنہ سے پوچھا، کیا تمہارے پاس نبی صلی اللہ علیہ وسلم کی تعلیمات میں سے قرآن کے علاوہ بھی کوئی چیز ہے؟ تو انہوں نے فرمایا، اس ذات کی قسم! جس نے دانے سے کونپل کو پھاڑا اور مخلوق کو پیدا کیا کچھ نہیں سوائے اس فہم کے جو کسی آدمی کو قرآن میں عطا کیا گیا اور جو کچھ اس صحیفہ میں ہے، میں نے پوچھا، صحیفہ میں کیا ہے؟ فرمایا: ’’دیت کے مسائل، قیدیوں کو چھڑوانے کے احکامات اور یہ کہ کسی مومن کو کافر کے بدلے قتل نہ کیا جائے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1625)","f":"۱۔ سیدنا علی بن ابی طالب رضی اللہ عنہ کے پاس کسی قسم کا کوئی خفیہ علم نہیں تھا بلکہ آپ بھی دیگر صحابہ کرام رضی اللہ عنہم کی طرح کتاب و سنت کے عالم و متبع تھے۔ ۲۔ سیدنا علی رضی اللہ عنہ کے عہد میں ان سے متعلق کچھ غلط باتیں مشہور ہوگئی تھیں تو سیدنا علی رضی اللہ عنہ نے ممکن حد تک ان کی تردید فرما دی۔ ۳۔ قرآن دانی اور شرعی مسائل کے استنباط میں سیدنا علی رضی اللہ عنہ کو خاص ملکہ حاصل تھا۔ ۴۔ صحابہ کرام رضی اللہ عنہم احادیث نبویہ کو لکھتے اور محفوظ کرتے تھے۔ ۵۔ کافر حربی ہو یا ذمی، اس کے بدلے مومن و مسلمان کو قتل نہیں کیا جائے گا۔"}],[1627,"عطاء، طاؤوس، مجاہد اور حسن رحمہم اللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فتح مکہ کے سال اپنے خطبہ میں فرمایا: ’’مسلمان کو کافر کے بدلے میں قتل نہیں کیا جائے گا۔‘‘ پوچھا یہ (روایت) مرسل ہے تو میں نے کہا: ہاں۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1626)"}],[1628,"زہری سے روایت ہے کہ شاس جذامی کے بیٹے نے شام کے نبطیوں میں سے ایک آدمی کو قتل کر دیا، جب یہ معاملہ عثمان بن عفان رضی اللہ عنہ کے سامنے لایا گیا تو انہوں نے قاتل کے قتل کا حکم دیا۔ پھر عثمان رضی اللہ عنہ سے زبیر اور رسول اللہ صلی اللہ علیہ وسلم کے دیگر صحابہ رضی اللہ عنہم نے بات چیت کی اور انہیں اس قتل سے روک دیا، فرمایا: آپ نے اس کی دیت ایک ہزار دینار مقرر کی۔ (1)","",{"k":"(1) اسنادہ ضعیف لانقطاعہ بین الزہری وسفیان بن حسین: البیہقی (8/33)، المعرفة السنن والآثار لہ (4816)۔"}],[1629,"سعید بن مسیب رحمہ اللہ سے روایت ہے فرمایا، ہر معاہد کی دیت ان کے عہد میں ایک ہزار دینار تھی۔ (1)","",{"k":"(1) اسنادہ ضعیف، فان سفیان بن حسین ضعیف فی الزہری خاصة: البیہقی فی المعرفة السنن والآثار لہ (4932)۔"}],[1630,"ابوشریح کعبی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس کا کوئی عزیز قتل کر دیا جائے تو اس کے وارثوں کو دو باتوں کا اختیار ہے۔ اگر وہ پسند کریں تو ان کے لیے دیت ہے، اور اگر وہ پسند کریں تو ان کے لیے قصاص ہے۔‘‘ (1)","",{"k":"(1) صحیح: البیہقی فی المعرفة السنن والآثار (4850)۔"}],[1631,"ایک دوسری سند سے ابوہریرہ رضی اللہ عنہ کے واسطہ سے نبی صلی اللہ علیہ وسلم سے سابقہ حدیث کی ہم مثل یا اس کے ہم معنی بھی مروی ہے۔ (1)","",{"k":"(1) البخاری (2434، 112)، مسلم (1355)۔"}],[1632,"ابوشریح کعبی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ والے سال فرمایا: ’’جس کا کوئی عزیز قتل کر دیا جائے تو اسے دو باتوں کا اختیار ہے، اگر چاہے تو دیت لے لے، اور اگر چاہے تو اس کے لیے قصاص ہے۔‘‘ ابوحنیفہ نے کہا، میں نے ابن ابی ذئب سے کہا، اے ابوالحارث کیا آپ اس حدیث کو لیں گے (یعنی اس پر عمل کریں گے)۔ (ابن ابی ذئب نے میرے سینے پر مارا اور مجھے برا بھلا کہا اور فرمایا، میں تجھے رسول اللہ صلی اللہ علیہ وسلم کی حدیث سناتا ہوں اور تو کہتا ہے کیا آپ اس کو اختیار کریں گے، ہاں میں اسے لوں گا اور یہ بات مجھ پر بھی اور ہر اس حدیث کو سننے والے پر فرض ہے۔ بے شک اللہ تعالیٰ نے محمد صلی اللہ علیہ وسلم کو لوگوں میں سے چنا اور ان کے ذریعے لوگوں کو ہدایت دی، اور لوگوں کے لیے بھی وہی دین پسند کیا جو آپ صلی اللہ علیہ وسلم کے لیے کیا۔ لہذا مخلوق پر واجب ہے کہ وہ آپ صلی اللہ علیہ وسلم کی ہر حالت میں اتباع کریں، کیونکہ ایک مسلمان کے لیے اس کے سوا کوئی چارہ نہیں۔ ابوحنیفہ نے کہا آپ مجھے یہ باتیں کہتے کہتے خاموش نہیں ہوئے حتی کہ میں نے تمنا کی کہ آپ خاموش ہو جائیں۔ (1)","",{"k":"(1) اسنادہ ضعیف (1631)۔"}],[1633,"ابوشریح کعبی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بے شک اللہ تعالیٰ نے مکہ کو حرمت والا شہر قرار دیا ہے، اس کو لوگوں نے حرمت والا نہیں قرار دیا، اللہ اور آخرت کے دن پر ایمان رکھنے والے کے لیے جائز نہیں کہ اس میں کسی کا خون بہائے، نہ اس زمین کا کوئی درخت کاٹے اور اگر کوئی آدمی اپنے لیے رخصت نکالے، تو فرمایا (اسے کہنا) یہ اللہ کے رسول صلی اللہ علیہ وسلم کے لیے حلال قرار دیا گیا، کیونکہ اللہ نے اس کو میرے لیے حلال قرار دیا ہے اور لوگوں کے لیے حلال قرار نہیں دیا، اور میرے لیے بھی دن کے تھوڑے حصے کے لیے حلال قرار دیا گیا، پھر یہ اسی طرح حرمت والا ہے جس طرح کل حرمت والا تھا۔ اے خزاعہ والو! یقیناً تم نے بنی ہذیل قبیلے کے آدمی کو قتل کیا ہے، اور اللہ کی قسم! میں اس کی دیت دینے والا ہوں۔ اور جس نے بعد میں کسی کو قتل کیا تو اس کے ورثاء کو دو باتوں کا اختیار ہے، اگر چاہیں تو (قصاص میں) قتل کریں اور اگر چاہیں تو دیت لے لیں۔‘‘ (1)","",{"k":"(1) البخاری (1832)، مسلم (1354)۔","f":"۱۔ مکہ مکرمہ حرم ہے اور حدود حرم میں قتل و غارت سنگین جرم ہے۔ ۲۔ نبی صلی اللہ علیہ وسلم نے مذکورہ بات فتح مکہ کے موقع پر ارشاد فرمائی تھی آپ کے لیے خاص طور پر تھوڑی مدت کے لیے مکہ کی حرمت اٹھائی گئی۔ ۳۔ مقتول کے ورثاء کو شریعت نے قصاص اور قبول دیت میں اختیار دیا ہے۔ جبکہ ایک تیسرے اختیار بالکل معاف کر دینے کا بھی قرآن میں ذکر موجود ہے۔ مزید دیکھیے فوائد حدیث نمبر: ۱۶۳۵۔ ۴۔ اللہ اور آخرت پر ایمان کا تقاضا ہے کہ آدمی احکام شرع کی پاسداری کرے۔"}],[1634,"مقاتل نے بیان کیا کہ میں نے یہ تفسیر حفاظ کی ایک جماعت سے لی ہے جن میں معاذ، مجاہد، حسن اور ضحاک بن مزاحم شامل ہیں۔ اللہ تعالیٰ کے فرمان ’’جس کسی کو اپنے بھائی کی طرف سے معافی دے دی جائے۔’’(البقرة: ۱۷۸) کے متعلق فرمایا کہ اہل تورات پر کسی کو ناحق قتل کرنے پر قصاص فرض تھا، نہ انہیں قصاص سے درگزر کی اجازت تھی اور نہ وہ دیت لے سکتے تھے۔ اور اہل انجیل پر معاف کر دینا فرض تھا، وہ قصاصاً قتل نہیں کر سکتے تھے، اور امت محمدیہ علی صاحبہا الصلاة والسلام کے لیے رخصت دی گئی، اگر چاہیں تو قتل کریں اگر چاہیں تو دیت لیں اور اگر چاہیں تو معاف کر دیں اور یہی اللہ کے فرمان:‘‘یہ تمہارے رب کی طرف سے تخفیف اور رحمت ہے’’کا مفہوم ہے۔ وہ فرماتے ہیں، کہ دیت اللہ تعالیٰ کی طرف سے تخفیف ہے جب دیت لے لی تو قتل نہیں کیا جائے گا۔ پھر فرمایا:‘‘اور جو اس کے بعد سرکشی کرے اس کے لیے دردناک عذاب ہے۔’’اور اللہ کے فرمان:‘‘تمہارے لیے قصاص میں زندگی ہے۔‘‘ کے متعلق فرمایا، اس سے تم ایک دوسرے کو قتل کرنے سے، قصاصاً قتل ہو جانے کے خوف کی وجہ سے باز آ جاتے ہو۔ (1)","",{"k":"(1) اسنادہ ضعیف فان معاذ بن موسی مجہول وبکیر بن معروف الأسدی لین: البیہقی (8/24، 51)، المعرفة السنن والآثار لہ (4487)۔"}],[1635,"مجاہد فرماتے ہیں میں نے ابن عباس رضی اللہ عنہما کو فرماتے ہوئے سنا کہ بنی اسرائیل پر قصاص فرض تھا اور ان میں دیت نہیں تھی تو اللہ تعالیٰ نے اس امت کے لیے فرمایا کہ تم پر مقتولوں کا قصاص فرض کر دیا گیا ہے، آزاد آزاد کے بدلے، غلام غلام کے بدلے، عورت عورت کے بدلے، اور جس کسی کو اپنے بھائی کی طرف سے معافی دے دی گئی تو اسے بھلائی کے پیچھے لگنا ہے اور اچھے طریقے سے اسے دیت ادا کرنی ہے، یہ تمہارے رب کی طرف سے تخفیف اور رحمت ہے۔’’وہ جو تم سے پہلے لوگوں پر فرض کیا گیا کہ‘‘جس نے اس کے بعد زیادتی کی اس کے لیے دردناک عذاب ہے۔“ (البقرة: ۱۷۸) (1)","",{"k":"(1) البخاری (4498)۔","f":"۱۔ بنی اسرائیل میں سے اہل تورات کے لیے قصاص یا معافی تھی جبکہ اہل انجیل کے لیے صرف معافی تھی قصاص یا دیت نہیں تھی۔ ۲۔ اللہ رب العزت کے امت محمدی صلی اللہ علیہ وسلم پر بے شمار احسانات میں سے یہ بھی ہے کہ اس نے سابقہ امم کے مقابلہ میں اس امت کے مقتول کے ورثاء کو تین باتوں میں سے ایک کا اختیار دیا ہے۔ ۳۔ زمانہ جاہلیت میں کوئی نظم و ضبط یا قانون نہیں تھا۔ طاقتور قبائل کمزور قبیلوں پر ظلم و زیادتی کرتے اور قتل و غارت کا ارتکاب کرتے اللہ تعالیٰ نے مذکورہ آیت کے ذریعے قاتل کو متنبہ کیا کہ تمہیں قتل کے بدلے قصاصاً قتل کیا جائے گا لہذا تھوڑے ہی عرصے میں سب محفوظ و مامون ہو گئے اور عرب کا معاشرہ امن و امان کی مثالی تصویر پیش کرنے لگا۔ ۴۔ بطور قصاص قاتل ہی کو قتل کیا جائے گا چاہے امیر، حکمران، طاقتور، مرد و عورت ہی کیوں نہ ہو ارشادِ باری تعالیٰ ہے: ﴿النَّفْسَ بِالنَّفْسِ﴾ (المائدہ: ۴۵) جان کے بدلے جان۔ ۵۔ معافی یا تو مقتول کے ورثاء کی طرف سے دیت لے کر ہوگی یا پھر بغیر دیت لیے محض رضائے الٰہی کے لیے ہوگی۔ ہر دو صورت میں قاتل کو مقتول کے ورثاء کے ساتھ احسان و نیکی کا حکم ہے۔ ۶۔ دیت لینے کے بعد قاتل کو قتل کرنا ظلم و زیادتی اور سرکشی ہے اور اس کی عند اللہ سزا دردناک عذاب ہے۔"}],[1636,"ابولیلی نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے کسی مومن کو ناحق قتل کیا تو اس نے اپنے ہاتھوں قصاص خرید لیا الا یہ کہ مقتول کے ورثاء راضی ہو جائیں۔ اور جو کوئی اس میں حائل ہو گیا تو اس پر اللہ کی لعنت اور اس کا غضب ہے، اللہ اس کا نہ نفل قبول کریں گے اور نہ ہی فرض۔‘‘ (1)","",{"k":"(1) اسنادہ ضعیف، لارسالہ: البیہقی فی المعرفة السنن والآثار (4799)، عبدالرزاق (17191)۔","f":"دیکھیے فوائد حدیث نمبر: ۱۶۳۹۔"}],[1637,"ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’خبردار! بے شک قتل خطا (شبہ) عمد کے مقتول میں جو کوڑے یا لاٹھی سے مر جائے سو مغلظہ اونٹنیاں (دیت کی) ہیں۔ ان میں سے چالیس حاملہ اونٹنیاں ہیں جن کے پیٹ میں بچے ہوں۔‘‘ (1)","",{"k":"(1) ابوداود (4549)، ابن ماجة (2628، 2627)، وصححہ ابن الجارود (773)، الالبانی فی صحیح ابوداود (3807)۔"}],[1638,"عقبہ بن اوس سے روایت ہے کہ نبی صلی اللہ علیہ وسلم کے ایک صحابی سے بھی اسی سابقہ حدیث کی طرح مروی ہے۔ (1)","",{"k":"(1) النسائی (4797، 4798، 4800)۔","f":"۱۔ قتل کی تین قسمیں ہیں۔ ۱۔ قتل عمد یعنی ارادہ و نیت سے کسی کو قتل کرنا۔ ۲۔ قتل خطا بغیر نیت و ارادہ کے کسی کا قتل ہو جانا۔ ۳۔ قتل شبہ عمد ایسا قتل جس میں قتل کا ارادہ و نیت نہ ہو بلکہ صرف مارنا پیٹنا مقصود ہو اور اس سے قتل عمد کا شبہ پیدا ہو اسی تیسری قسم کا ذکر مذکورہ حدیث میں ہے جیسا کہ کوڑے اور لاٹھی کے ذکر سے واضح ہے۔ ۲۔ معلوم ہوا شبہ عمد کی صورت میں مقتول کے ورثاء کو سو اونٹ بطور دیت ادا کیے جائیں گے جن میں سے چالیس حاملہ اونٹنیاں ہوں گی اور اس دیت کو دیت مغلظہ یعنی بھاری و ثقیل کہتے ہیں۔"}],[1639,"طاووس رضی اللہ عنہ سے روایت ہے انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کیا کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کسی بلوے میں مارا گیا، جو لڑنے والوں میں پتھر سے یا کوڑے سے یا چھڑی کی ضرب سے مارا گیا تو وہ قتل خطا ہے، اس کی دیت قتل خطا کی دیت ہے، اور جو ارادہ سے قتل کیا گیا تو اس (قاتل نے) اپنے ہاتھوں قصاص خرید لیا، اور جو کوئی اس میں حائل ہو گیا تو اس پر اللہ کی لعنت اور اس کا غضب ہے نہ اس سے نفلی عبادت قبول کی جائے گی اور نہ فرضی۔‘‘ (1)","",{"k":"(1) ابوداود (4539، 4540)، النسائی (4793)۔","f":"۱۔ ’’فی عمیة‘‘ کا مطلب ہے کسی جگہ لڑائی ہوئی اور اس میں کوئی شخص مارا گیا اور یہ بھی معلوم نہیں کہ قاتل کون ہے تو اس طرح بلوے میں قتل ہونے والے کا حکم قتل خطا کا ہے اس میں قصاص نہیں البتہ دیت دینا ہوگی۔ ۲۔ سنگباری، ڈنڈے، باری یا لاٹھی اور کوڑے وغیرہ سے مرنے والا بھی قتل خطا کے حکم میں ہے۔ ۳۔ قتل عمد میں قصاص ہے الا کہ مقتول کے ورثاء قبول دیت یا معافی پر راضی ہو جائیں۔ ۴۔ حدود اللہ کے نفاذ میں رکاوٹ بننا کبیرہ گناہ ہے۔ ۵۔ سربراہ مملکت کا خصوصی اختیار استعمال کرتے ہوئے قاتلوں کی پھانسیوں کو رکوا دینا یا انہیں معاف کر دینا درست نہیں ہے۔ ۶۔ گناہ نیکیوں کی قبولیت میں رکاوٹ بنتے ہیں اور ان کے انسان پر دنیا و آخرت میں انتہائی مہلک اثرات مرتب ہوتے ہیں۔"}],[1640,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’خبردار! بے شک قتل خطا (شبہ) عمد کے مقتول میں جو کوڑے اور لاٹھی سے ہو، سو اونٹنیاں ہیں، ان میں سے چالیس وہ حاملہ اونٹنیاں ہیں جن کے پیٹ میں بچے ہوں۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1637)","f":"دیکھیے فوائد حدیث نمبر: ۱۶۳۸۔"}],[1641,"عروہ رضی اللہ عنہ نے بیان فرمایا کہ ابوحذیفہ بن یمان رضی اللہ عنہ بوڑھے آدمی تھے۔ انہیں غزوہ احد کے دن عورتوں کے ساتھ بلند جگہ میں ٹھہرایا گیا۔ وہ وہاں سے شہادت کے لیے نکلے۔ پھر مشرکین کی جانب سے واپس آئے کہ مسلمانوں نے انہیں جلدی سے آلیا اور اپنی تلواروں سے ان کو کاٹ ڈالا، جبکہ (ان کے بیٹے) حذیفہ رضی اللہ عنہ صحابہ رضی اللہ عنہم سے فرما رہے تھے، یہ میرا باپ ہے، یہ میرا باپ ہے، جنگ کے شعلوں کی وجہ سے انہوں نے ان کی ایک نہ سنی یہاں تک کہ ان کو قتل کر دیا۔ پھر حذیفہ رضی اللہ عنہ نے فرمایا: اللہ تمہارے گناہ معاف کرے اور وہ سب سے زیادہ رحم کرنے والا ہے پھر نبی صلی اللہ علیہ وسلم نے ان کی دیت کی ادائیگی کا فیصلہ دیا۔ (1)","",{"k":"(1) اسنادہ ضعیف، لضعف مطرف وہو ابن مازن الکنانی: البیہقی (8/132)، المعرفة السنن والآثار لہ (4689)۔"}],[1642,"قیس بن ابی حازم سے روایت ہے فرمایا جعشم قبیلہ کے پاس قوم نے پناہ لی، پھر جب مسلمان ان پر غالب آگئے تو انہوں نے سجدہ کے ذریعے پناہ چاہی، مسلمانوں نے ان کے بعض کو قتل کر دیا، جب یہ بات نبی صلی اللہ علیہ وسلم تک پہنچی تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’ان کی نمازوں کی وجہ سے انہیں آدھی دیت دو۔’’پھر اس موقع پر ارشاد فرمایا:‘‘خبردار! میں ہر ایسے مسلمان سے بری ہوں جو مشرکوں کے پاس رہے۔’’صحابہ رضی اللہ عنہم نے پوچھا اے اللہ کے رسول صلی اللہ علیہ وسلم! اس کی کیا وجہ ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘دونوں کی آگ (آگاہی) نظر نہیں آنی چاہیے۔‘‘ (1)","",{"k":"(1) اسنادہ ضعیف لارسالہ، واسماعیل بن خالد مدلس وقد عنعن: الترمذی (1605)، النسائی (4784)۔"}],[1643,"عبداللہ بن ابوبکر نے اپنے باپ سے روایت کیا کہ وہ خط جو رسول اللہ صلی اللہ علیہ وسلم نے عمرو بن حزم رضی اللہ عنہ کے نام لکھا اس میں ہے کہ سو اونٹ ایک جان (کے قتل) میں ہیں۔ (1)","",{"k":"(1) النسائی (4861)، البیہقی (8/81، 89، 90)، وصححہ الحاکم (1/395، 397)، وابن حبان۔","f":"۱۔ ارشادِ باری تعالیٰ ہے: ﴿وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَئًا وَمَنْ قَتَلَ مُؤْمِنًا خَطَئًا فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ إِلَّا أَنْ يَصَّدَّقُوا﴾ (النساء: ۹۲) ’’کسی مومن کے لیے دوسرے مومن کو قتل کرنا جائز نہیں ہے مگر غلطی سے ہو جائے (تو اور بات ہے) جو شخص کسی مومن کو غلطی سے قتل کر دے اس کے ذمہ ایک مسلمان غلام کی گردن آزاد کرنا اور مقتول کے ورثاء کو خون بہا دینا ہے الا کہ وہ لوگ بطور صدقہ معاف کر دیں۔‘‘ ۲۔ ایک مسلمان آدمی کی دیت سو اونٹ ہے جن میں تیس ایک سال کی اونٹنیاں، تیس دو سالہ اونٹنیاں، تیس تین سالہ اونٹنیاں جبکہ دس دو سال کے اونٹ ہیں۔ (دیکھیے: سنن ابی داود، رقم: ۴۵۴۱) ۳۔ دیت کی اصل مقدار اونٹوں سے متعین ہوگی لیکن اگر اونٹ نہ ہوں گائیوں میں سے دو سو گائے اور بکریوں میں سے دو ہزار بکریاں بھی بطور دیت دی جا سکتی ہیں۔ (دیکھیے سنن ابن ماجہ، رقم: ۲۶۳۰)"}],[1644,"عبداللہ بن ابوبکر سے روایت ہے ان دیتوں کی کتاب کے متعلق جو رسول اللہ صلی اللہ علیہ وسلم کی طرف سے عمرو بن حزم رضی اللہ عنہ کے نام تھی میں ہے کہ ’’ایک جان میں سو اونٹ ہیں۔‘‘ ابن جریج نے کہا کہ میں نے عبداللہ بن ابوبکر سے پوچھا کیا آپ کو اس میں شک ہے یہ کہ وہ اللہ کی کتاب سے ہے؟ فرمایا: نہیں۔ (1)","",{"k":"(1) اسنادہ ضعیف لارسالہ والحدیث الذی قبلہ برقم (1643) یغنی عنہ۔ اخرجہ البیہقی: 8/ 73۔ وفی المعرفة السنن والآثار لہ (4682)."}],[1645,"ایک اور سند سے طاووس رضی اللہ عنہ کے واسطہ سے بھی اسی طرح ہے۔ (1)","",{"k":"(1) کتاب الأم (6/105)، مصنف عبدالرزاق (9/292)۔"}],[1646,"عمرو بن شعیب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بستی والوں کے لیے اونٹوں کی قیمت چار سو دینار یا اس کے برابر چاندی جس کو اونٹوں کی قیمت پر تقسیم کرتے تھے۔ اور جب مہنگے ہو جاتے تو اس کی قیمت بھی بڑھا دیتے اور جب سستے ہو جاتے تو اس کی قیمت سے بھی کمی کرتے۔ بستی والوں پر قیمت کی ادائیگی ہے جو بھی ہو۔ (1)","",{"k":"(1) اسنادہ ضعیف لاعضالہ، ولعنعنة ابن جریج ولضعف مسلم بن خالد: اخرجہ البیہقی: 7/ 76۔ 77۔ وفی المعرفة السنن والآثار لہ (4691).","f":"۱۔ دیت کی اصل مقدار تو اونٹ ہی ہیں تاہم اونٹوں کی عدم موجودگی میں سو اونٹوں کی قیمت کا اندازہ کر کے رقم بھی ادا کی جا سکتی ہے۔ ۲۔ عہد نبوی میں ان کی قیمت چار سو دینار سے آٹھ سو دینار کے درمیان رہی اور یہ چاندی کے حساب سے آٹھ ہزار درہم تھی۔ (دیکھیے ابن ماجہ، رقم: ۲۶۳۰) ۳۔ مارکیٹ میں اونٹوں کی قیمت میں اتار چڑھاؤ سے نقد رقم میں بھی کمی بیشی ہوگی۔ ۴۔ امیر المومنین سیدنا عمر رضی اللہ عنہ نے اپنے عہد خلافت میں جبکہ اونٹ مہنگے ہو گئے سونے والوں پر ایک ہزار دینار اور چاندی والوں پر بارہ ہزار درہم دیت مقرر فرمائی۔ (دیکھیے سنن ابی داود، رقم: ۴۵۴۲)"}],[1647,"مکحول اور عطاء رضی اللہ عنہما سے روایت ہے انہوں نے کہا، ہم نے لوگوں کو (یہ کہتے ہوئے) پایا کہ آزاد مسلمان کی دیت رسول اللہ صلی اللہ علیہ وسلم کے عہد میں سو اونٹ تھی۔ پھر عمر بن خطاب رضی اللہ عنہ نے یہ دیت بستی والوں پر ایک ہزار دینار یا بارہ ہزار درہم مقرر کر دی۔ اور بستی والوں میں سے آزاد مسلمان عورت کی دیت پانچ سو دینار یا سات ہزار درہم، جب اس کو قتل کرنے والا اعرابی ہو تو اس کی دیت پچاس اونٹ اور اعرابی عورت کی دیت جب اسے اعرابی قتل کرے تو بھی پچاس اونٹ مقرر کی، (اور فرمایا) اعرابی کو سونے، چاندی کی ادائیگی کا مکلف نہ بنایا جائے گا۔ (1)","",{"k":"(1) اسنادہ ضعیف لضعف مسلم بن خالد ولارسالہ اخرجہ البیہقی: 8/ 76، 95۔ وفی المعرفة السنن والآثار لہ (4619)۔ وابن ابی شیبة (26726)۔ وابوداود فی المراسیل (255)."}],[1648,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے بنی لحیان کی ایک عورت کے بچے کے بارے میں، جو کسی عورت کے مارنے سے مردہ پیدا ہوا تھا، خون بہا کے طور پر ایک غلام یا لونڈی دینے کا حکم دیا۔ پھر فرمایا کہ وہ عورت جس کے بارے میں آپ صلی اللہ علیہ وسلم نے فیصلہ دیا تھا فوت ہوگئی تو رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ دیا کہ اس کی میراث اس کے بیٹوں اور خاوند کے لیے ہے اور دیت کی ادائیگی اس کے عصبہ پر ہے۔ (1)","",{"k":"(1) البخاری (6740)، مسلم (1681)۔","f":"۱۔ جنین سے مراد وہ بچہ ہے جو حاملہ عورت کے پیٹ میں ہوا بھی پیدا نہ ہوا ہو۔ ۲۔ حاملہ عورت کے پیٹ پر چوٹ لگنے کی وجہ سے بچہ مردہ پیدا ہو تو اس کی دیت ایک غلام یا لونڈی ہے۔ ۳۔ دیت مقتول کا ترکہ ہے جو اس کے ورثاء میں تقسیم ہوگا۔ ۴۔ خاوند کا حصہ مقرر ہے اور یہ اصحاب الفروض میں سے ہے عصبہ میں شامل نہیں۔ ۵۔ اگر جنین کے ساتھ اس کی ماں بھی قتل ہو جائے تو یہ دو انسانوں کا قتل ہے ایسی صورت میں عورت کا حکم عام قتل کا ہوگا جس میں یا تو قصاص لازم آئے گا یا پھر مکمل دیت کی ادائیگی کرنا ہوگی اور جنین کی دیت ایک غلام یا لونڈی ہوگی۔"}],[1649,"امام شافعی رحمہ اللہ نے فرمایا، اگر کوئی کہے کہ وہ بات کیسے ہے جس میں نبی صلی اللہ علیہ وسلم نے جنین میں عورت کو دیت کی ادائیگی کا فیصلہ دیا؟ تو کہا جائے گا، ہمیں ثقہ نے خبر دی۔ ربیع نے کہا۔ وہ یحییٰ بن حسان ہیں۔ لیث بن سعد سے انہوں نے ابن شہاب سے انہوں نے ابن مسیب سے انہوں نے ابو ہریرہ رضی اللہ عنہ سے۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1648)"}],[1650,"ابن مسیب سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے اس بچے کے بارے میں جو اپنی ماں کے پیٹ میں قتل کر دیا جائے ایک غلام یا باندی دیت کا فیصلہ دیا، جس کے خلاف فیصلہ ہوا تھا اس نے کہا، میں ایسی چیز کی دیت کیسے دوں، جس نے نہ پیا ہے نہ کھایا ہے، نہ بات چیت کی ہے، اور نہ ہی ولادت کے وقت اس کی آواز سنائی دی ہے، اور اس صورت میں تو دیت نہ ہوگی؟ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ شخص کاہنوں کا بھائی لگتا ہے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1648)","f":"۱۔ قانون اللہ اور اس کے رسول کی بات ہے لہذا احکام شرع کے مقابل غیر سنجیدہ گفتگو جس کی عملی زندگی میں کچھ وقعت نہیں، درست نہیں ہے۔ ۲۔ کاہن بے کار، فضول اور اکثر جھوٹ پر مبنی گفتگو کرتے ہیں اس لیے نبی صلی اللہ علیہ وسلم نے شرعی فیصلے پر اعتراض کرنے والے کو کاہنوں کا بھائی کہا۔"}],[1651,"طاووس رحمہ اللہ سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ نے پوچھا ہے کوئی آدمی جس نے نبی صلی اللہ علیہ وسلم سے پیٹ کے بچے کے متعلق کچھ سنا ہو؟ تو حمل بن مالک بن نابغہ رضی اللہ عنہ کھڑے ہوئے اور فرمایا، میں اپنی دو سوکنوں کے درمیان رہتا تھا، کہ ان میں سے ایک نے دوسری کو خیمے کی چوب سے مارا، تو اس نے پیٹ کا بچہ مردہ جنا، اس میں رسول اللہ صلی اللہ علیہ وسلم نے ایک غلام یا لونڈی کا فیصلہ دیا۔ پھر عمر رضی اللہ عنہ نے فرمایا، قریب تھا کہ اس مسئلہ میں ہم اپنی رائے سے اسی طرح فیصلہ دے دیتے۔ (1)","",{"k":"(1) اخرجہ ابوداود (4572)۔ وابن ماجة، الدیات، باب دیة الجنین (2641)۔ والنسائی (4743) موصولاً وصححہ ابن حبان والحاکم: 3/ 575."}],[1652,"طاووس سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ نے فرمایا ہے کوئی آدمی جس نے نبی صلی اللہ علیہ وسلم سے جنین کے بارے میں کچھ سنا ہو؟ تو حمل بن مالک بن نابغہ رضی اللہ عنہ کھڑے ہوئے اور انہوں نے فرمایا، میں اپنی دو سوکنوں میں رہتا تھا کہ ان میں سے ایک نے دوسری کو خیمے کی چوب سے مارا تو اس نے پیٹ کا بچہ مردہ جنا، اس میں رسول اللہ صلی اللہ علیہ وسلم نے ایک غلام یا لونڈی کا فیصلہ دیا۔ پھر عمر رضی اللہ عنہ نے فرمایا، اگر ہم یہ بات نہ سنتے تو اس مقدمہ میں کوئی اور فیصلہ دے دیتے۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1651)","f":"۱۔ اگر کسی مسئلہ میں دلیل کا علم نہ ہو تو کتاب و سنت سے دلیل تلاش کرنا اور مکمل وسائل کو بروئے کار لانا ضروری ہے۔ ۲۔ قرآن و سنت کی بات آ جانے پر اس کی اتباع ضروری ہے۔ ۳۔ اللہ اور اس کے رسول کی بات کے مقابل اپنی رائے کو ترک کر دینا ہی سلف صالح صحابہ کرام رضی اللہ عنہم کا طرز عمل ہے۔"}],[1653,"ابن مسیب سے روایت ہے، انہوں نے فرمایا: غلام کی دیت اس کی قیمت میں ہے۔ (1)","",{"k":"(1) اسنادہ صحیح: البیہقی (8/104)، المعرفة السنن والآثار لہ (939)، ابن ابی شیبة (27194، 27218)۔"}],[1654,"سعید بن مسیب رحمہ اللہ سے روایت ہے انہوں نے فرمایا: غلام کی دیت اس کی قیمت میں ہے جس طرح کہ آزاد کا زخم اس کی دیت میں ہے۔ (1)","",{"k":"(1) اسنادہ صحیح: البیہقی (8/104)، المعرفة السنن والآثار لہ (940)، عبدالرزاق (18142)، ابن ابی شیبة (27219)۔","f":"معلوم ہوا غلام کی دیت اس کی قیمت کی ادائیگی ہے۔"}],[1655,"صدقہ بن یسار سے روایت ہے فرمایا، ہم نے سعید بن مسیب رحمہ اللہ کی طرف ایک پیغام بھیجا، ہم ان سے معاہد (ذمی) کی دیت کے متعلق پوچھ رہے تھے۔ تو انہوں نے فرمایا کہ عثمان بن عفان رضی اللہ عنہ نے اس میں چار ہزار کا فیصلہ دیا صدقہ کہتے ہیں ہم نے کہا، کس نے اس کو قتل کیا؟ فرمایا، پھر ہمیں کنکریاں ماریں۔ امام شافعی رحمہ اللہ نے فرمایا، یہ وہ لوگ ہیں جنہوں نے آخر میں ان سے یہ سوال کیا تھا۔ (1)","",{"k":"(1) اسنادہ صحیح: البیہقی (8/100)، المعرفة السنن والآثار لہ (930)، ابن ابی شیبة (27455)۔","f":"امام شافعی رحمہ اللہ کی بات کا مقصد یہ ہے کہ پہلے سعید بن مسیب رحمہ اللہ مذکورہ بات کے مخالف فتویٰ دیتے پھر انہوں نے اس سے رجوع فرما لیا اور صدقہ ان کے رفقاء نے ان کے رجوع فرمانے کے بعد ان سے یہ مسئلہ دریافت کیا۔ (واللہ اعلم بالصواب)"}],[1656,"صدقہ بن یسار سے روایت ہے ہم نے سعید بن مسیب رحمہ اللہ کی طرف پیغام بھیج کر یہودی اور عیسائی کی دیت کے متعلق پوچھا تو سعید رحمہ اللہ نے فرمایا، عثمان بن عفان رضی اللہ عنہ نے اس میں چار ہزار کی ادائیگی کا فیصلہ دیا۔ (1)","",{"k":"(1) انظر الحدیث الذی السابق (1655)"}],[1657,"سعید بن مسیب سے روایت ہے وہ عمر بن خطاب رضی اللہ عنہ سے کہ انہوں نے یہودی اور عیسائی میں چار ہزار کا اور مجوسی میں آٹھ سو (درہم) کا فیصلہ دیا۔","",{"f":"۱۔ ذمی کافر یہودی ہو یا عیسائی یا مجوسی اس کی دیت مسلمان کی دیت کا نصف ہے سیدنا عمرو بن شعیب عن ابیہ عن جدہ سے مروی ہے: ’’ان رسول اللہ صلی اللہ علیہ وسلم قضیٰ ان عقل اہل الکتابین نصف عقل المسلمین، وھم الیھود والنصاریٰ۔’’‘‘رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ اہل کتاب کا خون بہا مسلمانوں کے خون بہا سے نصف ہے اور اہل کتاب سے مراد یہودی اور عیسائی ہیں۔‘‘ (سنن ابن ماجہ، کتاب الدیات، باب دیة الکافر، رقم: ۲۶۴۴)"}],[1658,"عبداللہ بن ابوبکر نے اپنے باپ سے روایت کیا کہ وہ کتاب جسے رسول اللہ صلی اللہ علیہ وسلم نے عمرو بن حزم رضی اللہ عنہ کے لیے لکھا اس میں ہے، جب مکمل ناک کٹ جائے تو اس کی دیت سو اونٹ ہیں۔ اور سر کے زخم میں ایک جان کی دیت کا تیسرا حصہ ہے، پیٹ وغیرہ اور آنکھ کے زخم میں پچاس اور ہاتھ میں پچاس، اور پاؤں میں بھی پچاس ہیں اور ہر انگلی میں دس اونٹ اور دانت میں پانچ اور ہڈی کو ننگا کر دینے والے زخم کی دیت بھی پانچ اونٹ ہے۔ (1)","",{"k":"(1) صحیح بشواہدہ: البیہقی (8/100)، المعرفة السنن والآثار لہ (929)، عبدالرزاق (18485، 18489)، ابن ابی شیبة (27445)، النسائی (4821)، وصححہ الحاکم (1/395، 397)، ابن الجارود (784، 786)۔","f":"۱۔ قتل کی دیت سو اونٹ ہے لیکن اگر انسانی جسم کا کوئی عضو کٹ جائے تو اس کی اہمیت کے پیش نظر ہر عضو کی دیت مختلف ہے جس کی کچھ تفصیل اس حدیث میں بیان ہوئی ہے۔ ۲۔ ناک انسانی شکل و صورت اور وقار کا بنیادی عضو ہے لہذا اس کے کٹ جانے پر بھی مکمل سو اونٹ بطور دیت وصول کیے جائیں گے بشرطیکہ ناک کو جڑ سے مکمل کاٹا گیا ہو۔ ۳۔ ’’مأمومة’’ایسا زخم جو دماغ تک پہنچ جائے اور‘‘جائفة’’سے مراد پیٹ میں لگنے والا گہرا زخم ہے اور ایسے زخموں میں ثلث یعنی ایک تہائی دیت ہے۔ ۴۔‘‘الموضحة‘‘ ایسا زخم جو ہڈی کو گوشت سے ننگا کر دے اور ہڈی نظر آنے لگ جائے۔ اس کی دیت پانچ اونٹ ہے۔"}],[1659,"محمد بن عمرو بن حزم سے روایت ہے کہ وہ کتاب جو رسول اللہ صلی اللہ علیہ وسلم نے عمرو بن حزم رضی اللہ عنہ کے لیے لکھی اس میں ہے کہ ’’ہر ایک انگلی میں (دیت) دس اونٹ ہیں۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1658)"}],[1660,"ابو موسیٰ اشعری رضی اللہ عنہ نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’انگلیوں میں دس دس (اونٹ) ہیں۔‘‘ (1)","",{"k":"(1) صحیح بشواہدہ: ابوداود (4556)، ابن ماجة (2654)، النسائی (4849)، وصححہ ابن حبان۔","f":"۱۔ ہر انگلی میں دس اونٹ دیت ہے وہ انگلی ہاتھ کی ہو یا پاؤں کی جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «دیة اصابع الیدین والرجلین سواء» ”کہ ہاتھوں اور پاؤں کی انگلیوں کی دیت برابر ہے۔’’(سنن ترمذی، کتاب الدیات، باب ماجاء فی دیة الاصابع، رقم: ۱۳۹۱۔ وقال حسن صحیح غریب) ۲۔ چھینگی اور انگوٹھا کی دیت بھی برابر ہی یعنی دس اونٹ ہی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘ھذہ وھذہ سواء’’یعنی الخنصر والابھام‘‘ یا اور یہ یعنی چھینگی اور انگوٹھا (دیت میں) برابر ہیں۔ (صحیح بخاری، کتاب الدیات، باب دیة الاصابع، رقم ۶۸۹۵)"}],[1661,"سعید بن مسیب رحمہ اللہ سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ نے انگوٹھے میں پندرہ اور انگوٹھے سے ملی ہوئی (انگشت شہادت) میں دس، درمیان والی میں دس، چھینگی انگلی سے ملی ہوئی میں نو اور چھینگی انگلی میں چھ (اونٹوں کی دیت) کا فیصلہ دیا۔ (1)","",{"k":"(1) البیہقی (8/93)، المعرفة السنن والآثار لہ (4916)۔"}],[1662,"عمر بن خطاب رضی اللہ عنہ کے آزاد کردہ غلام اسلم رحمہ اللہ سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ نے ڈاڑھ میں ایک اونٹ، ہنسلی کی ہڈی میں ایک اونٹ اور پسلی میں بھی ایک اونٹ (دیت کا) فیصلہ دیا۔ (1)","",{"k":"(1) اسنادہ صحیح: البیہقی (8/99)، المعرفة السنن والآثار لہ (4927)۔"}],[1663,"ابو غطفان بن طریف مری نے بیان کیا کہ مروان بن حکم نے اسے ابن عباس رضی اللہ عنہ سے ڈاڑھ کی دیت پوچھنے کے لیے بھیجا۔ تو ابن عباس رضی اللہ عنہ نے فرمایا، اس میں پانچ اونٹ ہیں۔ (کہتے ہیں) مجھے مروان نے دوبارہ ابن عباس رضی اللہ عنہ کے پاس بھیجا اور کہا، کیا آپ منہ کے اگلے حصے کو ڈاڑھوں کی طرح خیال کرتے ہیں؟ تو ابن عباس رضی اللہ عنہ نے جواب دیا، اگر چہ تم اعتبار نہ کرو مگر تمام انگلیوں کی دیت تو برابر ہے۔ امام شافعی رحمہ اللہ نے فرمایا یہ حدیث اس بات پر دلالت کرتی ہے کہ دونوں ہونٹوں کی دیت بھی برابر ہے۔ اور ہونٹوں کی دیت میں اس کے علاوہ اور بھی صحابہ رضی اللہ عنہم سے آثار منقول ہیں۔","",{"f":"جس طرح تمام انگلیوں کی دیت برابر ہے اسی طرح تمام دانتوں کی دیت بھی ایک جیسی ہے وہ سامنے والے دانت ہوں یا داڑھیں ہوں اور وہ ہر دانت میں پانچ اونٹ دیت ہے۔"}],[1664,"عبداللہ بن ابوبکر نے اپنے باپ سے روایت کیا کہ وہ کتاب جو رسول اللہ صلی اللہ علیہ وسلم نے عمرو بن حزم رضی اللہ عنہ کے لیے لکھی اس میں ہے کہ ’’موضحہ (ہڈی کو ننگا کرنے والے زخم) میں پانچ اونٹ ہیں۔‘‘ (1)","",{"k":"(1) اسنادہ صحیح: اخرجہ البیہقی: 8/ 90۔ وفی المعرفة السنن والآثار لہ (4910)۔ اخرجہ مالک فی الموطا (1658)"}],[1665,"سعید بن مسیب رحمہ اللہ سے روایت ہے کہ عمر اور عثمان رضی اللہ عنہما نے ملطا (سر کر ہڈی اور گوشت کے درمیان چھلی کے کٹ جانے) میں موضحہ کی نصف دیت کا فیصلہ دیا۔ (1)","",{"k":"(1) اسنادہ ضعیف لا بہام شیخ الشافعی: البیہقی (8/83)، المعرفة السنن والآثار لہ (4903)۔"}],[1666,"ایک اور سند سے ابن مسیب کے واسطے سے عمر اور عثمان رضی اللہ عنہما سے سابقہ حدیث کی مثل مروی ہے۔ (1)","",{"k":"(1) سنن الکبری للبیہقی (8/83)، معرفة السنن والآثار (4904)، مصنف عبد الرزاق (8/124)۔"}],[1667,"امام شافعی رحمہ اللہ نے فرمایا جس نے نافع کے بیٹے سے سنا مجھے اس نے بتایا وہ مالک رحمہ اللہ سے اس سند کے ساتھ اسی (سابقہ حدیث) کی مثل روایت کرتا ہے۔ امام شافعی رحمہ اللہ نے فرمایا، اور ہم نے مالک رحمہ اللہ پر پڑھا، کہ ہم سلف اور موجودہ آئمہ میں سے کسی کو بھی نہیں جانتے جس نے موضحہ کے علاوہ کسی دوسرے زخم میں کسی چیز (کی دیت) کا فیصلہ دیا ہو۔ (1)","",{"k":"(1) ایضاً (7/268)۔"}],[1668,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جانور کا لگا ہوا زخم معاف ہے۔‘‘ (1)","",{"k":"(1) البخاری (1499)، مسلم (1710)۔","f":"۱۔ امام ابن ماجہ رحمہ اللہ حدیث کے معنی سے متعلق فرماتے ہیں: ’’والعجماء البهيمة من الانعام وغيرها، والجبار هو الهدر الذى لا يغرم‘‘ کہ ’’عجماء‘‘ سے مراد مویشی جانور وغیرہ ہیں اور ’’جبار‘‘ سے مراد وہ ہدر ہے جس کا کوئی تاوان نہ ہو۔ (سنن ابن ماجہ، تحت الحدیث: ۲۶۷۵)\n۲۔ امام ابوداود رحمہ اللہ فرماتے ہیں: ’’العجماء المنفلتة التي لا يكون معها احد وتكون بالنهار لا تكون بالليل‘‘ ’’جانور جب بھاگ گیا ہو اور اس کے ساتھ بھی کوئی نہ ہو اور یہ حادثہ دن کے وقت ہوا ہو رات میں نہ ہو۔‘‘ (سنن ابو داود، تحت الحدیث: ۴۵۹۳)\n۳۔ جانور چونکہ بے شعور مخلوق ہے لہذا اس کے کسی کو زخمی یا ہلاک کر دینے کی ذمہ داری مالک پر نہ ہوگی اور وہ زخم وغیرہ رائیگاں ہے اس پر دیت یا قصاص کا مطالبہ نہیں کیا جائے گا۔"}],[1669,"یعلی بن امیہ رضی اللہ عنہ سے روایت ہے فرمایا، میں نے نبی صلی اللہ علیہ وسلم کے ساتھ ایک غزوہ میں شرکت کی۔ صفوان رضی اللہ عنہ نے کہا، اور یعلی رضی اللہ عنہ فرماتے تھے کہ یہ غزوہ میرے خیال میں میرے دوسرے اعمال کی نسبت زیادہ قابل بھروسہ تھا۔ عطاء نے کہا، صفوان نے کہا، یعلی رضی اللہ عنہ نے فرمایا، میرا ایک مزدور تھا، وہ ایک انسان سے لڑ پڑا، ان میں سے ایک نے دوسرے کے ہاتھ پر دانت سے کاٹا، جس کا ہاتھ کاٹا جا رہا تھا اس نے کاٹنے والے کے منہ سے اپنے ہاتھ کو کھینچا تو اس کا سامنے والے دانتوں میں سے ایک دانت ٹوٹ گیا وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا تو آپ صلی اللہ علیہ وسلم نے اس کے اگلے دانت کو رائیگاں بنا دیا۔ عطاء نے کہا، میرے خیال میں انہوں نے فرمایا کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’کیا وہ اپنا ہاتھ تیرے منہ میں چھوڑ دیتا کہ تو اسے ایسے چبا جاتا جیسے اونٹ اپنے منہ میں چباتا ہے۔‘‘ عطاء نے کہا مجھے صفوان نے بتایا تھا کہ کس نے دانت سے کاٹا تھا لیکن میں بھول گیا ہوں۔ (1)","",{"k":"(1) البخاری (2265)، مسلم (1673، 1674)۔","f":"۱۔ مذکورہ واقعہ غزوہ تبوک کا ہے یہ غزوہ ۹ ہجری کو شدید گرمی میں ہوا جس کی وجہ سے مسلمان مجاہدین کو بہت سی تکالیف کا سامنا کرنا پڑا اس کو احادیث میں ’’جیش العسرة‘‘ بھی کہا گیا ہے۔\n۲۔ معلوم ہوا میدان جہاد میں کسی کو بطور مزدور ساتھ لے کر جانا درست ہے۔\n۳۔ حملہ آور کے مقابلے میں اپنا دفاع کرنا ضروری ہے۔\n۴۔ اگر کوئی شخص اپنے دفاع میں کسی کو زخمی یا قتل کر دے تو اس پر دیت اور کفارہ نہیں ہے۔"}],[1670,"ابو ملیکہ نے بیان فرمایا کہ ایک انسان ابوبکر صدیق رضی اللہ عنہ کے پاس آیا، اور اس کو ایک دوسرے انسان نے دانت سے کاٹا تو اس نے اپنا ہاتھ اس سے کھینچا کہ اس کا ایک سامنے کا دانت گر گیا، تو ابوبکر رضی اللہ عنہ نے فرمایا، اس کا سامنے کا دانت رائیگاں چلا ہو گیا۔ (1)","",{"k":"(1) البخاری (2266)۔"}],[1671,"ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر کوئی شخص تیرے گھر میں بغیر اجازت کے جھانکے اور تم اسے کنکری مار دو جس سے اس کی آنکھ پھوٹ جائے تو تجھ پر کوئی گناہ نہیں۔‘‘ (1)","",{"k":"(1) اخرجہ البخاری (6888)، (6902) ومسلم (2158).","f":"۱۔ کسی کے گھر میں بغیر اجازت جھانکنا غیر شرعی اور غیر اخلاقی حرکت ہے۔\n۲۔ اگر کوئی جھانکنے والے کی آنکھ پھوڑ دے تو اس میں قصاص یا دیت نہیں ہے۔"}],[1672,"سہل بن سعد رضی اللہ عنہ بیان فرماتے ہیں کہ ایک آدمی نے نبی صلی اللہ علیہ وسلم کے کسی حجرہ میں سوراخ سے دیکھا، (اس وقت) نبی صلی اللہ علیہ وسلم کے پاس ایک کنگھا تھا جس سے سر مبارک کھجا رہے تھے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اگر مجھے معلوم ہوتا کہ تم جھانک رہے ہو تو میں یہی کنگھا تیری آنکھ میں چبھ دیتا، کیونکہ اجازت کا مطالبہ تو دیکھنے کی وجہ سے ہے۔‘‘ (1)","",{"k":"(1) اخرجہ البخاری (6241) ومسلم (2156)","f":"۱۔ انسان کو اپنے گھر والوں کے معاملہ میں انتہائی غیرت مند ہونا چاہیے۔\n۲۔ نظر کی وجہ سے اجازت طلب کرنے کا حکم ہے جب جھانکنے سے گھر والوں پر نظر پڑ جائے تو اجازت کا مطالبہ بے مقصد ہو جاتا ہے لہذا اجازت لے کر اندر جھانکنا چاہیے۔ اسی بات کا حکم اللہ تعالیٰ نے قرآن میں بھی دیا ہے۔ ارشادِ باری تعالیٰ ہے:\n﴿ يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّى تَسْتَأْنِسُوا وَتُسَلِّمُوا عَلَى أَهْلِهَا ذَلِكُمْ خَيْرٌ لَكُمْ لَعَلَّكُمْ تَذَكَّرُونَ ﴾ [النور: ۲۷]\n’’اے ایمان والو! اپنے گھروں کے علاوہ دوسروں کے گھروں میں نہ جاؤ جب تک تم ان سے اجازت نہ لے لو اور (باہر کھڑے ہو کر) السلام علیکم نہ کہہ لو، (یہ اجازت طلب کرنا اور سلام کرنا) تمہارے لیے بہتر ہے تاکہ تم نصیحت حاصل کرو۔‘‘\n۳۔ رسول اللہ صلی اللہ علیہ وسلم کو علم غیب نہیں تھا۔"}],[1673,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے گھر میں تشریف فرما تھے کہ ایک آدمی کو دیکھا جس نے آپ صلی اللہ علیہ وسلم کو جھانکا تھا، تو آپ صلی اللہ علیہ وسلم نے اس کی طرف تیر کا پھل جھکایا جو آپ کے ہاتھ میں تھا، گویا کہ اگر وہ پیچھے نہ ہٹتا تو آپ کو اس بات کی کوئی پرواہ نہ تھی کہ اس پھل سے اس کی آنکھ چبھ جاتی۔ (1)","",{"k":"(1) اخرجہ البخاری (6889) ومسلم (2157).","f":"معلوم ہوا گھر والا جھانکنے والے کو زخم لگا دے تو کچھ حرج نہیں اور وہ اسے کسی بھی چیز سے سزا دے سکتا ہے۔ مزید فوائد کے لیے دیکھئے حدیث سابق۔"}],[1674,"سہل بن ابی حثمہ رضی اللہ عنہ سے روایت ہے۔ انہوں نے اور ان کی قوم کے بڑے لوگوں نے خبر دی کہ عبد اللہ بن سہل بن ابی حثمہ اور محیصہ دونوں خیبر کی طرف مالی مشکلات کی وجہ سے گئے۔ جب وہ دونوں اپنی اپنی ضروریات کے لیے الگ ہوئے تو محیصہ کو خبر آئی کہ عبد اللہ بن سہل تو قتل کر دیئے گئے ہیں اور انہیں ایک کنویں یا چشمے کے پاس پھینک دیا گیا ہے۔ محیصہ یہودیوں کے پاس آئے اور ان سے کہا، اللہ کی قسم! تم ہی لوگوں نے انہیں قتل کیا ہے۔ انہوں نے کہا، اللہ کی قسم! ہم نے انہیں نہیں مارا۔ پھر محیصہ (خیبر سے لوٹ کر) اپنی قوم والوں کے پاس آئے اور انہیں یہ واقعہ سنایا۔ پھر وہ اور ان کے بڑے بھائی حویصہ اور مقتول کے بھائی عبد الرحمن بن سہل نبی صلی اللہ علیہ وسلم کے پاس آئے۔ محیصہ چونکہ خیبر میں اس وقت موجود تھے اس لیے انہوں نے گفتگو شروع کر دی تو رسول اللہ صلی اللہ علیہ وسلم نے محیصہ سے فرمایا: ’’بڑے کو بات کرنے دو۔’’یعنی جو عمر میں بڑا ہے۔ پھر حویصہ نے بات کی بعد میں محیصہ نے بات کی، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘یا تو وہ تمہارے ساتھی (عبد اللہ) کی دیت دیں اور یا پھر انہیں جنگ کا نوٹس دیا جائے۔’’پھر رسول اللہ صلی اللہ علیہ وسلم نے انہیں اس مقدمہ کے سلسلہ میں لکھا، تو انہوں نے جواب میں لکھا، اللہ کی قسم! ہم نے انہیں قتل نہیں کیا۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے حویصہ، محیصہ اور عبد الرحمن سے کہا:‘‘تم قسم کھاؤ تو تمہارے ساتھی کا خون ان پر ثابت ہو جائے گا۔’’انہیں نے کہا، ہم قسم نہیں کھاتے۔ آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘پھر یہود قسم کھائیں گے۔‘‘ انہوں نے کہا، نہیں وہ تو مسلمان نہیں ہیں۔ آخر رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے عبد اللہ کی دیت میں سو اونٹنیاں انہیں دے دیں۔ یہاں تک کہ یہ اونٹنیاں ان کے گھر پہنچا دی گئیں۔ سہل نے کہا، ان میں سے ایک سرخ اونٹنی نے مجھے لات دے ماری تھی۔ (1)","",{"k":"(1) البخاری (7192)، مسلم (1669)۔","f":"۱۔ جب کوئی شخص کسی جگہ قتل ہو جائے اور اس کے قاتل نامعلوم ہوں جبکہ مقتول کے ورثاء کچھ قرائن کی بنیاد پر کسی قبیلے یا فرد پر قتل کا دعویٰ دائر کر دیں تو مدعی پچاس قسموں کے ساتھ اپنے دعوئی کو ثابت کریں گے کہ ہمارے مقتول کے قاتل فلاں قبیلے کے افراد یا فلاں فرد ہے۔ اگر مدعی قسمیں نہ اٹھائیں تو مدعا علیہ پچاس قسمیں اپنی صفائی میں کھا کر بری ہو جائیں گے کہ ہم قاتل نہیں، ایسے مقتول کی دیت بیت المال سے ادا کی جائے گی۔ اس سارے عمل کا نام ’’قسامت‘‘ ہے۔\n۲۔ قسامت کا یہی طریقہ کار جاہلیت میں موجود تھا شریعت اسلامیہ نے اس پر مہر تصدیق لگا دی۔ سیدنا سلیمان بن یسار رحمہ اللہ، ایک انصاری صحابی رضی اللہ عنہ سے بیان فرماتے ہیں: ’’ان رسول اللہ صلی اللہ علیہ وسلم اقرّ القسامة علی ما کانت علیہ في الجاهلية‘‘ بے شک رسول اللہ صلی اللہ علیہ وسلم نے قسامت کو اسی پر برقرار رکھا جس پر جاہلیت میں تھی۔ (صحیح مسلم، کتاب القسامة والمحاربين، باب القسامة، رقم: ۱۶۷۰)\n۳۔ جاہلیت کی پہلی قسامت سے متعلق سیدنا ابن عباس رضی اللہ عنہ بیان فرماتے ہیں (لمبی حدیث میں ہے) قاتل معین شخص تھا ابو طالب اس کے پاس آئے اور کہا تین چیزوں میں سے کسی ایک کو پسند کر لو۔ (i)...... اگر چاہو تو سو اونٹ بطور دیت دے دو کیونکہ تم نے ہمارے آدمی کو قتل کیا ہے۔ (ii)...... اگر چاہو تو تمہارے قبیلے کے پچاس افراد اس بات کی قسم دیں کہ تم نے ہمارے آدمی کو قتل نہیں کیا۔ (iii)...... اگر تم اس کے لیے بھی تیار نہیں تو ہم قصاصاً تمہیں قتل کریں گے۔ وہ شخص اپنی قوم والوں کے پاس آیا تو انہوں نے قسم دینے پر آمادگی ظاہر کی۔ پھر بنو ہاشم کی ایک عورت جو اس قبیلے کے ایک شخص کی بیوی تھی اور اس سے اس کا ایک بچہ بھی تھا ابو طالب کے پاس آئی اور کہنے لگی آپ میرے بیٹے کو ان پچاس آدمیوں میں سے معاف فرما دیں اور جہاں قسمیں لی جاتی ہیں اس سے وہاں قسم نہ لیں۔ ابو طالب نے اسے معاف کر دیا، اسی قبیلے کا ایک اور آدمی ابو طالب کے پاس آیا اور کہنے لگا، اے ابو طالب آپ نے سو اونٹوں کی جگہ پچاس آدمیوں سے قسم طلب کی اس لحاظ سے ہر آدمی کے حصے دو اونٹ آتے ہیں آپ مجھ سے دو اونٹ لیں اور مجھے اس مقام (رکن اور مقام ابراہیم کے درمیان) پر قسم کے لیے مجبور نہ کریں، ابو طالب نے اس کی بات بھی قبول کر لی پھر باقی اڑتالیس آدمیوں نے قسم اٹھائی۔ ابن عباس کہتے ہیں:\n’’فوالذی نفسی بیدہ ماحال الحول، ومن الثمانية واربعين عين تطرف‘‘\n’’مجھے اس ذات کی قسم جس کے ہاتھ میں میری جان ہے ابھی اس واقعہ کو ایک سال بھی نہیں گزرا تھا کہ ان اڑتالیس آدمیوں میں سے ایک بھی ایسا نہیں تھا جو آنکھ ہلا سکتا ہو۔‘‘\n(صحیح بخاری، کتاب مناقب الانصاری، باب القسامة في الجاهلية، رقم: ۳۸۴۵)\n۴۔ اسلامی حکومت میں کسی کا بھی خون رائیگاں نہیں جا سکتا۔\n۵۔ اگر کفار پر مشتبہ مسلمان مقتول کا دعویٰ دائر ہو اور وہ دیت دینے اور قسمیں اٹھانے سے انکار کر دیں تو ان سے مسلمان مقتول کا بدلہ لینے کے لیے جنگ کرنا جائز ہے۔\n۶۔ قسامت میں غیر مسلموں کی قسموں کا بھی اعتبار کیا جائے گا بشرطیکہ فریق ثانی راضی ہو۔\n۷۔ اگر معاملہ مشتبہ ہو تو دیت کی ادائیگی بیت المال سے ہو گی۔\n۸۔ بڑوں کے ادب و احترام کا تقاضا ہے کہ مجلس میں بڑوں کی موجودگی میں چھوٹے پہلے گفتگو نہ کریں۔"}],[1675,"سہل بن ابی حثمہ رضی اللہ عنہ سے روایت ہے کہ عبد اللہ بن سہل اور محیصہ بن مسعود رضی اللہ عنہما خیبر کی طرف گئے، پھر دونوں اپنی ضروریات کے لیے علیحدہ علیحدہ ہو گئے کہ عبد اللہ بن سہل قتل کر دیئے گئے۔ پھر محیصہ، مقتول کا بھائی عبد الرحمن اور حویصہ بن مسعود رسول اللہ صلی اللہ علیہ وسلم کے پاس چلے آئے، انہوں نے آپ صلی اللہ علیہ وسلم سے عبد اللہ بن سہل کے قتل کا واقعہ بیان کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم پچاس قسمیں کھاؤ اور اپنے مقتول یا اپنے ساتھی کی دیت کے مستحق ہو جاؤ گے۔’’انہوں نے کہا اے اللہ کے رسول صلی اللہ علیہ وسلم! ہم تو اس وقت وہاں موجود نہ تھے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘پھر یہود پچاس قسموں سے تم سے چھٹکارا پا لیں گے۔‘‘ انہوں نے عرض کیا اے اللہ کے رسول صلی اللہ علیہ وسلم! ہم کافر قوم کی قسموں کو کیسے قبول کریں۔ اس نے خیال کیا کہ نبی صلی اللہ علیہ وسلم نے اس کی دیت اپنی طرف سے ادا کر دی۔ بشیر بن یسار نے کہا کہ سہل نے فرمایا، مجھے ان دیت کے اونٹوں میں سے ایک اونٹنی نے تھان (اونٹوں کا باڑا) میں لات دے ماری۔ (1)","",{"k":"(1) البخاری (6143، 6142، 2702)، مسلم (1669)۔"}],[1676,"سہل بن ابی حثمہ اور ان کی قوم کے بڑے لوگوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے حویصہ، محیصہ اور عبد الرحمن سے کہا: ’’تم قسمیں دو گے تو اپنے ساتھی کے خون کے مستحق ٹھہرو گے۔’’انہوں نے کہا، نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘پھر یہود قسم کھائیں گے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1674)"}],[1677,"سہل بن ابی حثمہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ابتدا انصاریوں سے کی جب انہوں نے قسمیں نہ اٹھائیں تو آپ صلی اللہ علیہ وسلم نے قسموں کو یہودیوں پر لوٹا دیا۔ (1)","",{"k":"(1) مسلم (1669)۔","f":"معلوم ہوا پہلے مدعی افراد میں سے پچاس آدمی قسمیں کھا کر اپنا دعوئی ثابت کریں گے پھر فریق مخالف سے قسمیں لی جائیں گی۔"}],[1678,"ایک اور سند سے بشیر بن سیار کے واسطہ سے نبی صلی اللہ علیہ وسلم سے سابقہ حدیث کی مثل مروی ہے۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1677)"}],[1679,"سلیمان بن یسار رحمہ اللہ سے روایت ہے کہ بنی سعد بن لیث میں سے ایک آدمی نے گھوڑا دوڑایا اور جہینہ قبیلہ کے ایک آدمی کی ایک انگلی کچلی دی، اس میں خون جاری ہوا اور وہ آدمی فوت ہو گیا۔ عمر رضی اللہ عنہ نے انگلی کچلنے والے کی قوم سے کہا تم پچاس قسمیں کھاتے ہو کہ وہ آدمی انگلی کچلنے سے نہیں مرا؟ تو انہوں نے قسمیں کھانے سے انکار کر دیا۔ پھر دوسروں (میت کے ورثا) سے کہا تم قسمیں کھاؤ تو انہوں نے بھی انکار کر دیا اور وہ قسمیں کھانے سے رک گئے۔ (1)","",{"k":"(1) اسنادہ ضعیف لانقطاعہ فان سلیمان بن یسار لم یسمع من عمر: اخرجہ البیہقی: 125/ 8 و 10/ 183، 184۔ وفی المعرفة السنن والآثار لہ (5944)۔ وعبدالرزاق (18297)۔ وابن ابی شیبة (27629)."}],[1680,"عبد الرحمن بن ابی بکرہ نے اپنے باپ سے روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قاضی یا کوئی ثالث دو آدمیوں کے درمیان غصہ کی حالت میں فیصلہ نہ کرے۔‘‘ (1)","",{"k":"(1) البخاری (7158)، مسلم (1717)۔"}],[1681,"عبد الرحمن بن ابی بکرہ نے اپنے باپ سے روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’حاکم یا قاضی دو آدمیوں کے درمیان حالت غصہ میں فیصلہ نہ کرے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1680)","f":"۱۔ لوگوں کے باہمی اختلافات کا فیصلہ ایک اہم ذمہ داری ہے صحیح فیصلوں سے معاشرے امن و امان کا گہوارہ بنتے ہیں اور غلط فیصلوں کا نتیجہ بدامنی کی صورت میں سامنے آتا ہے۔ اس لیے شریعت اسلامیہ نے قاضی کی ذہنی حالت سے متعلق یہ بات کہی ہے کہ وہ غصے میں فیصلہ نہ دے کیونکہ ایسی حالت میں عموماً معاملات کے تمام پہلوؤں پر غور کرنا ممکن نہیں ہوتا اور فیصلہ کے غلط ہونے کے امکانات موجود ہوتے ہیں۔\n۲۔ غصے کے علاوہ شدید غم، کسی بیماری کی وجہ سے تکلیف وغیرہ بھی ایسی کیفیتیں ہیں جو انسان کی یکسوئی کو متاثر کرتی ہیں۔\n۳۔ رسول اللہ صلی اللہ علیہ وسلم معصوم عن الخطا ہیں اس لیے آپ صلی اللہ علیہ وسلم کے دیگر لوگوں کے برعکس حالت غصہ میں کیے ہوئے فیصلے درست اور وحی الہی کے مطابق تھے۔"}],[1682,"زہری سے روایت ہے کہ ابو ہریرہ رضی اللہ عنہ نے فرمایا میں نے رسول اللہ صلی اللہ علیہ وسلم سے زیادہ کسی کو بھی اپنے ساتھیوں سے مشورہ کرتے نہیں دیکھا ہے۔ امام شافعی رحمہ اللہ نے فرمایا: اور اللہ تعالیٰ نے فرمایا: ’’اور ان کے معاملات آپس میں مشورہ سے ہوتے ہیں۔‘‘ (الشوری: ۳۸) (1)","",{"k":"(1) اسنادہ ضعیف لانقطاعہ فان الزہری لم یسمع من ابی ہریرة: البیہقی (7/45، 46)، المعرفة السنن والآثار لہ (5862)، عبدالرزاق (9720)۔","f":"۱۔ مذکورہ روایت اگر چہ سنداً کمزور ہے تاہم رسول اللہ صلی اللہ علیہ وسلم کے صحابہ کرام رضی اللہ عنہم سے مشاورت کے بکثرت واقعات ذخیرہ احادیث میں موجود ہیں۔ مثلاً:\n(i) جنگ بدر سے قبل\n(ii) جنگ بدر کے قیدیوں سے متعلق\n(iii) واقعہ افک میں\n(iv) بنو ہوازن کے بچے اور قیدی خواتین واپس کرنے سے متعلق وغیرہ\n۲۔ نبی صلی اللہ علیہ وسلم وحی کے متبع تھے اور اللہ رب العزت کا بھی حکم یہی تھا کہ ﴿وَشَاوِرْهُمْ فِي الْأَمْرِ﴾ (آل عمران: ۱۵۹) اور ان سے آپ معاملات میں مشاورت کیجیے۔ اور آپ صلی اللہ علیہ وسلم اور صحابہ کرام کی اسی مشاورت کو ﴿وَأَمْرُهُمْ شُورَى بَيْنَهُمْ﴾ (الشوری: ۳۸) اور ان کا ہر کام باہمی مشورے سے ہوتا ہے میں بیان کیا گیا ہے۔"}],[1683,"سالم سے روایت ہے کہ عمر رضی اللہ عنہ لوگوں کے ساتھ واپس آگئے عبدالرحمن بن عوف رضی اللہ عنہ کی حدیث سے (جو انہوں نے طاعون والے علاقے میں نہ جانے کے متعلق رسول اللہ صلی اللہ علیہ وسلم سے بیان کی تھی) یعنی جب وہ شام کے لیے (مدینہ سے) نکلے تھے اور انہیں وہاں طاعون کی وبا پھیلنے کی اطلاع ملی تھی۔ (1)","",{"k":"(1) صحیح ثبت موصولاً: البخاری (6973)، مسلم (2219)۔","f":"۱۔ مذکورہ روایت اگرچہ سنداً کمزور ہے تاہم یہ بات صحیح احادیث سے ثابت ہے کہ سیدنا عمر رضی اللہ عنہ ۱۸ھ میں شام کے لیے روانہ ہوئے تو راستے میں ان کی سیدنا ابو عبیدہ بن جراح رضی اللہ عنہ اور ان کے ساتھیوں سے ملاقات ہوئی تو انہوں نے سرزمین شام میں طاعون کی وبا سے متعلق انہیں آگاہ کیا، سیدنا عمر رضی اللہ عنہ نے پہلے ہجرت میں سبقت اختیار کرنے والے مہاجرین سے مشاورت کی، پھر انصار سے، پھر قریش کے مشائخ سے پھر عبدالرحمن بن عوف رضی اللہ عنہ نے انہیں حدیث رسول سنائی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «اذا سمعتم به بارض فلا تقدموا عليه واذا وقع بارض وانتم بها فلا تخرجوا فراراً منه» ’’جب تمہیں کسی علاقے میں (وباء) کے واقع ہونے کا پتہ چلے تو اس علاقے میں نہ جاؤ اور اگر تم وہاں رہتے ہو جہاں وباء پھوٹ پڑے تو اس سے راہ فرار اختیار کرتے ہوئے نہ بھاگو۔‘‘ (صحیح بخاری، کتاب الطب، باب ما یذکر فی الطاعون، رقم: ۵۷۲۹۔ صحیح مسلم، رقم: ۲۲۱۹) ۲۔ معلوم ہوا رسول اللہ صلی اللہ علیہ وسلم کی طرح خلفاء راشدین بھی باہم مشاورت سے اہم امور کے فیصلے صادر فرماتے تھے۔"}],[1684,"ابو جعفر محمد بن علی سے روایت ہے کہ جب عمر رضی اللہ عنہ نے (لوگوں کو وظائف دینے کے لیے) رجسٹر مرتب کروائے تو فرمایا تمہارے خیال میں کن سے میں ابتداء کروں؟ تو انہیں مشورہ دیا گیا اپنے سب سے قریبی رشتہ داروں سے آغاز کیجیے۔ فرمایا، بلکہ میں تو رسول اللہ صلی اللہ علیہ وسلم کے سب سے زیادہ قریبی رشتہ داروں سے آغاز کروں گا۔ (1)","",{"k":"(1) اسنادہ ضعیف لانقطاعہ، فان ابا جعفر لم یسمع من عمر: البیہقی (6/364)، المعرفة السنن والآثار لہ (4016)۔"}],[1685,"عمرو بن عاص رضی اللہ عنہ سے روایت ہے انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: ’’جب حاکم فیصلہ اجتہاد سے کرے اور اس کا فیصلہ درست ہو تو اس کے لیے دہرا اجر ہے اور جب حاکم اجتہاد سے فیصلہ کرے اور غلطی کر جائے تو اس کے لیے اکہرا اجر ہے۔‘‘ (1)","",{"k":"(1) البخاری (7352)، مسلم (1716)۔","f":"۱۔ اگر صاحب علم قاضی بھر پور کوشش کرے اور پھر صحیح فیصلہ کرنے میں کامیاب ہو جائے تو اس کے لیے دو گنا ثواب ہے اور اگر کوشش کے باوجود صحیح فیصلہ نہ کر سکے تو اس کی غلطی بھی اس کے لیے باعث اجر ہے۔ ۲۔ لوگوں کے تنازعات کا خاتمہ کرنے اور جھگڑوں کا فیصلہ کرنے کے لیے ضروری ہے کہ حاکم و قاضی صاحب علم ہو کیونکہ اللہ نے وحی الہی کے مطابق فیصلہ کرنے کا حکم دیا ہے فرمایا: ﴿وَ أَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنْزَلَ اللَّهُ﴾ (المائدہ: ۴۹) ’’اور آپ لوگوں کے درمیان اللہ کی اتاری ہوئی وحی کے مطابق فیصلہ کیجیے۔‘‘ اور جو شخص وحی کے علم (کتاب وسنت) کو نہیں جانتا وہ قاضی و مجتہد نہیں ہوسکتا۔ ۳۔ سرسری سماعت پر معاملے کی تہہ تک پہنچے بغیر فیصلہ دینا درست نہیں۔ ۴۔ اجتہادی غلطی سے حق تبدیل نہیں ہوتا لہذا اگر اجتہادی غلطی واضح ہو جائے تو اس سے رجوع کرنا بہتر ولازم ہے۔"}],[1686,"ہمیں عبدالعزیز بن محمد نے یزید بن ہاد سے بیان کیا اس نے کہا کہ میں نے یہ حدیث ابوبکر بن محمد بن عمرو بن حزم کو بیان کی تو انہوں نے کہا مجھے ابوسلمہ بن عبدالرحمن نے ابو ہریرہ رضی اللہ عنہ سے بیان فرمایا۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1685)"}],[1687,"عمرو بن عاص رضی اللہ عنہ سے روایت ہے انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: ’’جب حاکم اجتہاد سے فیصلہ کرے اور فیصلہ درست ہو تو اس کے لیے دہرا اجر ہے اور جب حاکم اجتہاد سے فیصلہ دے اور غلطی کرے تو اس کے لیے اکہرا اجر ہے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1685)","f":"۱۔ دیکھیے فوائد حدیث نمبر: ۱۶۸۵۔"}],[1688,"یزید بن ہاد نے کہا میں نے یہ حدیث ابوبکر بن محمد بن عمرو بن حزم سے بیان کی تو انہوں نے فرمایا مجھے یہ حدیث اسی طرح ابو سلمہ نے ابو ہریرہ رضی اللہ عنہ کے واسطہ سے بیان کی۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1686)"}],[1689,"اُمّ المومنین سیدہ ام سلمہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بے شک میں انسان ہوں، اور تم اپنے باہمی جھگڑے میرے پاس لاتے ہو، اور ممکن ہے تم میں سے کوئی اپنا مقدمہ پیش کرنے میں دوسرے کی نسبت چالاک زبان والا ہو اور جو میں اس سے سنتا ہوں میں اس پر اس کے لیے فیصلہ دے دوں، جس کے لیے میں اس کے بھائی کے حق سے فیصلہ دے دوں تو وہ اسے ہرگز نہ لے کیونکہ اس طرح میں اس کے لیے جہنم کا ایک ٹکڑا کاٹ دیتا ہوں۔‘‘ (1)","",{"k":"(1) البخاری (7169)، مسلم (1713)۔"}],[1690,"ام سلمہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بے شک میں تمہارے جیسا انسان ہوں، اور تم اپنے جھگڑے میرے پاس لاتے ہو، ممکن ہے تم میں سے کوئی اپنا مقدمہ پیش کرنے میں دوسرے کی نسبت چالاک زبان والا ہو اور جو میں اس سے سنتا ہوں اس پر اس کے لیے فیصلہ دے دوں، جس کے لیے میں اس کے بھائی کے حق سے فیصلہ دوں تو وہ اس سے نہ لے کیونکہ اس طرح میں اس کے لیے جہنم کا ایک ٹکڑا کاٹ دیتا ہوں۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1690)","f":"۱۔ قاضی کا فیصلہ صرف ظاہر میں نافذ ہوتا ہے باطن میں نہیں یعنی قاضی کے فیصلے سے کوئی حلال چیز حرام یا حرام حلال نہیں ہو سکتی مثلاً کوئی آدمی کسی عورت سے متعلق اپنی منکوحہ ہونے کا دعویٰ دائر کرے اور اس پر گواہ بھی پیش کر دے جبکہ حقیقتاً وہ اس کی بیوی نہ ہو تو اس طرح قاضی کے فیصلے سے وہ اس کی منکوحہ نہیں بنے گی اور اس کے ساتھ ازدواجی تعلقات اسے عند اللہ مجرم بنا دیں گے۔ ۲۔ قاضی کو چاہیے کہ فریقین کی مکمل گفتگو سنے، پھر دلائل اور گواہوں کی گواہی اور دیگر قرائن کی بنیاد پر فیصلہ دے۔ ۳۔ چالاکی سے ناجائز طور پر فیصلہ اپنے حق میں کروا لینا آخرت کی رسوائی کا باعث ہے لہذا ظالم کو یہ بات جان لینی چاہیے کہ وہ اپنے بھائی کا حق مار کر آگ کا ٹکڑا لے رہا ہے۔ ۴۔ یہ حدیث رسول اللہ صلی اللہ علیہ وسلم کے بشر ہونے پر واضح دلیل ہے۔ ۵۔ نبی صلی اللہ علیہ وسلم کو علم غیب نہیں تھا عالم الغیب صرف اللہ رب العزت کی وحدہ لا شریک ذات ہے۔"}],[1691,"حرام بن سعد بن محیصہ سے روایت ہے کہ براء بن عازب رضی اللہ عنہ کی اونٹنی ایک قوم کے باغ میں داخل ہوئی اور اس کو تباہ کر دیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ دیا کہ دن کو مال کی حفاظت مالکوں کے ذمہ ہے اور رات کو جو مویشی نقصان کریں، تو اس کا ضامن ان کا مالک ہے۔ (یعنی رات کو ہونے والا نقصان جانور کے مالک سے لیا جائے گا۔) (1)","",{"k":"(1) حدیث صحیح وانظر الحدیث الآتی: ابن ماجة (2332)، ابوداود (3569)۔"}],[1692,"حرام بن محیصہ سے روایت ہے۔ انہوں نے براء بن عازب رضی اللہ عنہ سے روایت کیا کہ براء بن عازب رضی اللہ عنہ کی اونٹنی ایک انصاری کے باغ میں گھس گئی، اور اس نے اس کو تباہ کر دیا تو رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ دیا کہ باغ والوں پر اس کی دن کو نگرانی کرنا فرض ہے اور رات کو جو نقصان مویشی کریں وہ مویشیوں والوں پر (تاوان) ہے۔ (1)","",{"k":"(1) ابوداود (3570)، ابن ماجة (2332)، صححہ الحاکم (2/47، 48)، ووافقہ الذہبی والالبانی فی الصحیحة (238)۔","f":"۱۔ ارشاد باری تعالیٰ ہے: ﴿وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا وَجَعَلْنَا اللَّيْلَ لِبَاسًا وَجَعَلْنَا النَّهَارَ مَعَاشًا﴾ (النباء: ۱۰ - ۱۲) ’’اور ہم نے تمہاری نیند کو آرام کا سبب بنایا اور ہم نے رات کو تمہارا اوڑھنا مقرر کیا اور ہم نے دن کو وقت روزگار بنایا۔‘‘ اللہ تعالیٰ نے دن کو کام اور رات کو آرام کے لیے بنایا ہے دن کے وقت عموماً کھیت وغیرہ میں کام ہوتا ہے اس لیے اگر کسی کا جانور آ جائے تو اسے روکنا آسان ہے لہذا دن کے وقت کھیت وغیرہ کی حفاظت مالک کی ذمہ داری ہے۔ ۲۔ رات کو لوگ گھروں میں سوئے ہوتے ہیں اور مویشی بھی باڑوں میں ہوتے ہیں ایسی صورت میں اگر کسی کا جانور کسی کھیت وغیرہ کا نقصان کر دے تو اس نقصان کی تلافی جانور کا مالک کرے گا کیونکہ جانور کا کھلا رہنا مالک کی سستی و کاہلی کی دلیل ہے۔"}],[1693,"ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’گواہی پیش کرنا مدعی کے ذمہ ہے۔’’میرے خیال میں انہوں نے کہا اور میں اسے یاد نہیں رکھ سکا کہ انہوں نے یہ بھی فرمایا کہ‘‘(گواہ نہ ہونے کی صورت میں) قسم مدعی علیہ پر ہے۔‘‘ (1)","",{"k":"(1) البخاری (4552)، مسلم (1711)۔","f":"۱۔ اس حدیث میں ایک اہم اصول بیان کیا گیا ہے کہ مدعی اپنا دعویٰ دلائل اور گواہوں سے ثابت کرے اگر وہ ایسا نہ کر سکے تو مدعی علیہ قسم دے کر اپنی صفائی پیش کرے گا۔"}],[1694,"جابر بن عبد اللہ رضی اللہ عنہ سے روایت ہے کہ دو آدمیوں نے ایک جانور پر دعویٰ کیا اور ہر ایک نے گواہی پیش کر دی کہ یہ اس کا جانور ہے جسے اس نے بچہ جننے کے لیے تیار کیا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس کا فیصلہ اس کے حق میں دیا وہ جس کے ہاتھ میں تھا۔ (1)","",{"k":"(1) اسنادہ ضعیف جداً فان ابن ابی یحییٰ واسحاق بن ابی فروة متروکان: البیہقی (10/256)، المعرفة السنن والآثار لہ (5984)، الدارقطنی (4/209)، البغوی (2504)۔"}],[1695,"انس رضی اللہ عنہ سے روایت ہے کہ انہوں نے اپنے بیٹے میں شک کیا تو اس کے لیے قیافہ لگانے والے کو بلایا۔ (1)","",{"k":"(1) اسنادہ صحیح: البیہقی (10/264)، المعرفة السنن والآثار لہ (6003)، ابن ابی شیبة (17494)۔","f":"۱۔ قائف جو علم قیافہ کو جانتا ہو، ہاتھ، پاؤں، چہرہ، اعضاء دیکھ کر آدمی کے باطنی اخلاق دریافت کرے یا یہ معلوم کر لے کہ (یہ) فلاں کا بیٹا ہے یا بھائی ہے۔ باپ اور بیٹے میں مشابہت دیکھ کر (اس کی جمع قافت)۔ (لغات الحدیث: ۳/ ۶۲۳) ۲۔ سیدہ عائشہ بیان فرماتی ہیں ایک قیافہ لگانے والا میرے گھر میں داخل ہوا، نبی صلی اللہ علیہ وسلم بھی (گھر میں) تشریف فرما تھے جبکہ اسامہ بن زید اور زید بن حارثہ لیٹے ہوئے تھے تو اس نے کہا: یہ پاؤں ایک دوسرے سے نکلے ہیں۔ تو نبی صلی اللہ علیہ وسلم کو یہ بات بہت پسند آئی پھر آپ صلی اللہ علیہ وسلم نے یہ بات عائشہ رضی اللہ عنہا کو بھی بتلائی۔ (صحیح بخاری، کتاب فضائل اصحاب النبی باب مناقب زید بن حارثہ، رقم: ۳۷۳۱)"}],[1696,"یحیی بن عبدالرحمن بن حاطب سے روایت ہے کہ دو آدمیوں نے ایک بچہ کا دعویٰ کیا، تو عمر رضی اللہ عنہ نے قیافہ لگانے والوں کو بلایا، تو انہوں نے کہا، یہ دونوں اس میں شریک ہیں۔ تو پھر عمر رضی اللہ عنہ نے اس بچے سے کہا ان دونوں میں سے جس کے پاس چاہے چلا۔ (1)","",{"k":"(1) اسنادہ ضعیف لانقطاعہ فان یحیی بن عبدالرحمن بن حاطب لم یدرک عمر: البیہقی (10/263)، المعرفة السنن والآثار لہ (6000)۔"}],[1697,"ایک اور سند سے سلیمان بن یسار کے واسطہ سے عمر رضی اللہ عنہ سے سابقہ حدیث کے ہم معنی مروی ہے۔ (1)","",{"k":"(1) اسنادہ ضعیف لانقطاعہ فان سلیمان بن یسار لم یسمع من عمر: البیہقی (10/263)، المعرفة السنن والآثار لہ (1697)، الطحاوی فی شرح المعانی (4/161)۔"}],[1698,"ایک اور سند سے عروہ بن زبیر کے واسطہ سے بھی عمر رضی اللہ عنہ بن خطاب سے اسی کی ہم معنی مروی ہے۔ (1)","",{"k":"(1) اسنادہ ضعیف جداً: بشدة ضعف مطرف بن مازن ولانقطاعہ فان عروة بن الزبیر لم یسمع من عمر: البیہقی (10/263)، المعرفة السنن والآثار لہ (6002)۔"}],[1699,"ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ سعد (بن عبادہ) رضی اللہ عنہ نے فرمایا: اے اللہ کے رسول صلی اللہ علیہ وسلم! اگر میں اپنی بیوی کے ساتھ کسی مرد کو پاؤں تو کیا اسے چار گواہ لانے تک مہلت دوں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہاں۔‘‘ (1)","",{"k":"(1) مسلم (1498)۔"}],[1700,"ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ سعد رضی اللہ عنہ نے عرض کیا، اے اللہ کے رسول صلی اللہ علیہ وسلم! اگر میں اپنی بیوی کے ساتھ کسی مرد کو پاؤں تو کیا چار گواہ لانے تک اسے مہلت دوں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہاں۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1699)","f":"۱۔ زنا کی حد کے نفاذ کے لیے چار عینی گواہوں کا ہونا ضروری ہے۔ ارشاد باری تعالیٰ ہے: ﴿وَالَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ ثُمَّ لَمْ يَأْتُوا بِأَرْبَعَةِ شُهَدَاءَ فَاجْلِدُوهُمْ ثَمَانِينَ جَلْدَةً وَلَا تَقْبَلُوا لَهُمْ شَهَادَةً أَبَدًا وَأُولَئِكَ هُمُ الْفَاسِقُونَ﴾ (النور: ۴) ’’اور جو پاک دامن عورتوں پر زنا کی تہمت لگائیں پھر چار گواہ پیش نہ کرسکیں تو انہیں اسی کوڑے لگاؤ اور آئندہ کبھی بھی ان کی گواہی قبول نہ کرو یہ لوگ فاسق ہیں۔‘‘ ۲۔ شرعی حدود کے نفاذ سے قبل دلیل کا ہونا ضروری ہے۔ ۳۔ شادی شدہ زانی کی سزا رجم اور غیر شادی شدہ زانی کی سزا سو کوڑے اور سال کی جلا وطنی ہے۔ دیکھیے حدیث نمبر: ۱۵۶۹، ۱۵۷۳۔"}],[1701,"ابن مسیب سے روایت ہے کہ علی بن ابی طالب رضی اللہ عنہ سے ایک ایسے آدمی سے متعلق پوچھا گیا: جس نے اپنی بیوی کے ساتھ کسی دوسرے مرد کو پایا اور اس کو قتل کر دیا یا اپنی عورت کو قتل کر دیا تو فرمایا، اگر چار گواہ نہ لائے تو خود قتل پر تیار ہو جائے۔ (1)","",{"k":"(1) انظر الحدیث الآتی برقم (1702)"}],[1702,"سعید بن مسیب سے روایت ہے کہ شام میں ایک آدمی نے اپنی بیوی کے ساتھ غیر مرد کو پایا تو اسے قتل کر دیا یا اس عورت کو قتل کر دیا۔ تو (شام کے حاکم) معاویہ رضی اللہ عنہ نے ابو موسیٰ اشعری رضی اللہ عنہ کو لکھا کہ ان کے لیے تم یہ مسئلہ علی رضی اللہ عنہ سے پوچھو۔ انہوں نے علی رضی اللہ عنہ سے پوچھا تو آپ نے فرمایا، یہ واقعہ عراق کی سرزمین میں نہیں ہوا، میں آپ کو قسم دیتا ہوں کہ سچ بیان کرو، پھر انہوں نے حقیقت بتا دی، تو علی رضی اللہ عنہ نے فرمایا: ’’میں ابوالحسن ہوں، اگر وہ چار گواہ نہیں لاتا تو قتل پر راضی ہو جائے۔‘‘ (1)","",{"k":"(1) اسنادہ صحیح: اخرجہ البیہقی: 8/ 230، 10/ 147۔ وفی المعرفة السنن والآثار لہ (5277)۔ وعبدالرزاق (17915)، (17916) وابن ابی شیبة (27879)۔ ومالک فی الموطا، الاقضیة، باب القضاء فیمن وجد مع امرأتہ رجلاً.","f":"۱۔ قانون کو اپنے ہاتھ میں لینا درست نہیں۔ ۲۔ حدود کو قائم کرنا اسلامی حکومت کا کام ہے۔ ۳۔ اگر کوئی شخص اپنی بیوی کے ساتھ کسی کو بدکاری کرتے دیکھے اور غیرت میں آ کر اسے قتل کر دے جبکہ اس کے پاس چار گواہ بھی نہ ہوں تو ایسی صورت میں قاتل قتل کا ذمہ دار ہوگا اور اس سے قصاص لیا جائے گا۔ ۴۔ سیدنا علی رضی اللہ عنہ قضایا میں مہارت تامہ رکھتے تھے اور سیدنا معاویہ رضی اللہ عنہ بھی علمی مسائل میں ان کی طرف رجوع فرماتے تھے۔"}],[1703,"سفیان بن عیینہ رحمہ اللہ نے بیان کیا کہ میں نے زہری رحمہ اللہ سے سنا، انہوں نے فرمایا کہ عراق والے یہ سمجھتے ہیں کہ تہمت لگانے والے کی شہادت جائز نہیں ہے۔ اور میں گواہی دیتا ہوں کہ مجھے سعید بن مسیب رحمہ اللہ نے بتایا کہ عمر بن خطاب رضی اللہ عنہ نے ابوبکرہ سے کہا، تو توبہ کر لے تو تیری گواہی قبول کی جائے گی یا اگر تو توبہ کرتا ہے تو تیری گواہی قبول کی جائے گی۔ امام شافعی رحمہ اللہ نے فرمایا، میں نے سفیان بن عیینہ رحمہ اللہ کو کئی دفعہ اسی طرح بیان کرتے ہوئے سنا پھر میں نے ان کو فرماتے ہوئے سنا کہ مجھے اس میں شک ہوا ہے۔ امام شافعی رحمہ اللہ نے فرمایا: میں گواہی دیتا ہوں کہ مجھے فلاں نے بتایا، پھر آدمی کا نام لیا جسے میں یاد نہ رکھ سکا تو میں نے ان سے پوچھا تو مجھے عمر بن قیس نے بتایا کہ وہ سعید بن مسیب سے روایت کرتے ہیں۔ اور سفیان رحمہ اللہ، سعید بن مسیب کے متعلق شک نہیں کرتے تھے۔ امام شافعی رحمہ اللہ نے فرمایا: اور ان کے علاوہ کوئی اور اسے ابن شہاب سے روایت ہے وہ سعید بن مسیب رحمہ اللہ سے اور وہ عمر رضی اللہ عنہ سے روایت کرتے ہیں۔ (1)","",{"k":"(1) اسنادہ صحیح: البیہقی (10/152)، المعرفة السنن والآثار لہ (5891)، ابن ابی شیبة (20648)، الطبری فی تفسیرہ (18/76)۔","f":"ارشادِ باری تعالیٰ ہے:\n﴿ وَالَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ ثُمَّ لَمْ يَأْتُوا بِأَرْبَعَةِ شُهَدَاءَ فَاجْلِدُوهُمْ ثَمَانِينَ جَلْدَةً وَلَا تَقْبَلُوا لَهُمْ شَهَادَةً أَبَدًا وَأُولَئِكَ هُمُ الْفَاسِقُونَ ﴾ [النور: ۴]\n’’اور جو پاک دامن عورتوں پر زنا کی تہمت لگائیں پھر چار گواہ پیش نہ کر سکیں تو انہیں اسی کوڑے لگاؤ اور آئندہ کبھی بھی ان کی گواہی قبول نہ کرو یہ لوگ فاسق ہیں۔‘‘\nاس آیت میں قاذف (بہتان تراشی کرنے والے) کے لیے تین حکم بیان ہوئے ہیں۔\n۱۔ حد قذف اسی کوڑے\n۲۔ ان کی آئندہ کبھی بھی گواہی قبول نہ کی جائے\n۳۔ ایسے لوگ فاسق ہیں۔ جبکہ اس سے اگلی آیت میں اللہ تعالیٰ فرماتے ہیں:\n﴿ إِلَّا الَّذِينَ تَابُوا مِنْ بَعْدِ ذَلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ ﴾ [النور: ۵]\n’’مگر جو لوگ اس کے بعد توبہ اور اصلاح کرلیں تو بے شک اللہ تعالیٰ بخشنے والے اور مہربانی کرنے والے ہیں۔‘‘\nاس آیت سے معلوم ہوتا ہے کہ اگر قاذف توبہ کرنے کے بعد اپنی اصلاح کرلے تو آئندہ کے لیے اس کی شہادت قبول کی جاسکتی ہے۔ (واللہ اعلم بالصواب)"}],[1704,"ہمیں سفیان بن عیینہ نے خبر دی انہوں نے کہا مجھے زہری نے خبر دی۔ پھر جب ہم (مجلس برخاست کر کے) کھڑے ہوئے تو مجھے عمر بن قیس نے کہا جو میرے ساتھ مجلس میں موجود تھے کہ وہ سعید بن مسیب ہیں میں نے سفیان رحمہ اللہ سے پوچھا کیا سعید بن مسیب رحمہ اللہ نے آپ کو خبر دی اسی وقت آپ کو شک لاحق ہوا؟ فرمایا، نہیں وہ اسی طرح ہی ہے جس طرح انہوں نے فرمایا البتہ انہوں نے مجھے شک میں ڈال دیا۔ (1)","",{"k":"(1) اسنادہ صحیح: البیہقی (10/152)، المعرفة السنن والآثار لہ (5891)۔"}],[1705,"سعید بن مسیب رحمہ اللہ سے روایت ہے کہ جب عمر بن خطاب رضی اللہ عنہ نے تین آدمیوں کو حد (قاذف) لگائی تو ان سے توبہ کروائی، ان میں سے دو نے رجوع کر لیا تو ان دونوں کی شہادت کو قبول کیا، جبکہ ابوبکرہ نے رجوع سے انکار کر دیا تو ان کی گواہی کو بھی رد کر دیا۔ (1)","",{"k":"(1) اسنادہ ضعیف لابہام شیخ الشافعی: البیہقی (10/152)، المعرفة السنن والآثار لہ (5892)۔"}],[1706,"ابن جریج سے روایت ہے انہوں نے عطاء رحمہ اللہ سے کہ انہوں نے عورتوں کی گواہی عورتوں کے کسی معاملہ میں قبول کرنے کے متعلق فرمایا، چار سے کم کی گواہی اس میں جائز نہیں ہے۔ (1)","",{"k":"(1) اسنادہ ضعیف لضعف مسلم بن خالد الزنجی: البیہقی (10/152)، المعرفة السنن والآثار لہ (5884)، ابن ابی شیبة (20713)۔"}],[1707,"عطاء رحمہ اللہ سے روایت ہے انہوں نے فرمایا: عورتوں کے معاملے میں عورتوں کی گواہی کہ ان کے ساتھ کوئی مرد نہ ہو تو چار عادل عورتوں سے کم کی جائز نہیں ہے۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1706)"}],[1708,"ابن ابی ملیکہ سے روایت ہے کہ ابن عباس رضی اللہ عنہ نے بچوں کی گواہی کے متعلق فرمایا، جائز نہیں ہے۔ ابن جریج نے ابن ابی ملیکہ سے ابن عباس رضی اللہ عنہ کے واسطہ سے یہ الفاظ زیادہ بیان کیے۔ کیونکہ اللہ تعالیٰ فرماتے ہیں: ’’جنہیں تم گواہوں میں سے پسند کرو۔‘‘ (البقرہ: ۳۸۳) (1)","",{"k":"(1) اسنادہ صحیح: البیہقی (10/162)، المعرفة السنن والآثار لہ (5898)۔"}],[1709,"ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قسم کے ساتھ ایک گواہ پر فیصلہ دیا۔ (1)","",{"k":"(1) مسلم (1712)۔","f":"۱۔ مدعی کے پاس اپنا دعویٰ ثابت کرنے کے لیے دو گواہوں کا ہونا ضروری ہے اگر دو مرد گواہ نہ ہوں تو ایک مرد اور دو عورتوں کی گواہی بھی درست ہے۔ ارشادِ باری تعالیٰ ہے:\n﴿ وَاسْتَشْهِدُوا شَهِيدَيْنِ مِنْ رِجَالِكُمْ فَإِنْ لَمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَامْرَأَتَانِ مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَدَاءِ ﴾ [البقرة: ۲۸۲]\n’’اور اپنے میں سے دو مرد گواہ رکھ لو، اگر دو مرد نہ ہوں تو ایک مرد اور دو عورتیں جنہیں تم گواہوں میں سے پسند کرو۔‘‘\n۲۔ اگر مدعی کے پاس صرف ایک گواہ ہو تو اس گواہ کی شہادت اور مدعی کی قسم کے ساتھ فیصلہ ہوگا۔\n۳۔ سیدنا علی رضی اللہ عنہ نے بھی قسم اور ایک گواہ کے ساتھ فیصلہ کیا۔ (سنن ترمذی، رقم: ۱۳۴۵)\n۴۔ امام ترمذی رحمہ اللہ فرماتے ہیں بعض صحابہ اور دیگر اہل علم کے نزدیک اس بات پر عمل موجود ہے کہ حقوق اور مالی معاملات میں قسم اور ایک گواہ کے ساتھ فیصلہ درست ہے امام مالک بن انس، امام شافعی، امام احمد بن حنبل اور امام اسحاق رحمہم اللہ کا یہی مذہب ہے۔ (سنن ترمذی، کتاب الاحکام، باب ماجاء فی الیمین مع الشاہد تحت الحدیث: ۱۳۴۵)\n۵۔ احناف کے نزدیک مدعی پر قسم نہیں ہے ہدایہ میں ہے۔ لا ترد الیمین علی المدعی، یعنی مدعی پر قسم نہیں لوٹائی جائے گی۔ (ہدایة: ۲/ ۳۰۳)"}],[1710,"معاذ بن عبد الرحمن سے روایت ہے انہوں نے ابن عباس رضی اللہ عنہ اور ایک دوسرے آدمی سے جس کا انہوں نے نام لیا، اب مجھے اس کا نام یاد نہیں ہے۔ نبی صلی اللہ علیہ وسلم کے صحابہ میں سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قسم کے ساتھ ایک گواہ پر فیصلہ دیا۔ (1)","",{"k":"(1) اسنادہ ضعیف جداً الا ان المتن صحیح: البیہقی (10/168)، المعرفة السنن والآثار لہ (5911)۔"}],[1711,"ابن مسیب رحمہ اللہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قسم کے ساتھ ایک گواہ پر مقدمہ کا فیصلہ دیا۔ (1)","",{"k":"(1) اسنادہ ضعیف جداً لضعف شیخ الشافعی الا ان المتن صحیح: البیہقی (10/172)، المعرفة السنن والآثار لہ (5920)۔"}],[1712,"سعید بن عمرو بن شرحبیل بن سعید بن سعد بن عبادہ سے روایت ہے وہ اپنے باپ سے ان کے دادا سے روایت ہے فرمایا: ہم نے سعد رضی اللہ عنہ کی کتابوں میں لکھا ہوا پایا کہ رسول اللہ صلی اللہ علیہ وسلم نے قسم کے ساتھ ایک گواہ پر فیصلہ دیا۔ (1)","",{"k":"(1) الترمذی (1343)۔"}],[1713,"عمرو بن شرحبیل نے بیان فرمایا کہ ہم نے سعد بن عبادہ رضی اللہ عنہ کی کتابوں میں پایا، سعد بن عبادہ رضی اللہ عنہ گواہی دیتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عمرو بن حزم رضی اللہ عنہ کو حکم دیا کہ وہ ایک قسم کے ساتھ ایک گواہ پر فیصلہ دیں۔ (1)","",{"k":"(1) ضعیف من حدیث سعد، وقد صح من حدیث غیرہ: البیہقی (10/171)، المعرفة السنن والآثار لہ (5912)۔"}],[1714,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک قسم کے ساتھ ایک گواہ پر فیصلہ دیا۔ (1)","",{"k":"(1) اخرجہ ابوداود (3610)۔ والترمذی (1343)۔ وقال ’’حسن غریب‘‘ وابن ماجة، الاحکام، باب القضاء بالشہد والیمین (2368)۔ وصححہ ابن الجارود (1007)۔ وابن حبان."}],[1715,"جعفر بن محمد نے اپنے باپ سے روایت کیا کہ نبی صلی اللہ علیہ وسلم نے قسم کے ساتھ ایک گواہ پر فیصلہ دیا۔ (1)","",{"k":"(1) اسنادہ ضعیف لإرسالہ الا ان المتن صحیح کما تقدم: البیہقی (10/169، 173)، الترمذی (1345)۔"}],[1716,"جعفر بن محمد نے بیان کیا کہ میں نے حکم بن عتیبہ کو اپنے باپ سے پوچھتے ہوئے سنا جبکہ انہوں نے کھڑے ہونے کے لیے قبر کی دیوار پر ہاتھ رکھا ہوا تھا۔ (پوچھا) کیا نبی صلی اللہ علیہ وسلم نے قسم کے ساتھ ایک گواہ پر فیصلہ دیا؟ تو فرمایا: ہاں اور اسی طرح تمہارے درمیان علی رضی اللہ عنہ نے بھی فیصلہ دیا۔ (1)","",{"k":"(1) اسنادہ ضعیف لإرسالہ الا ان المتن صحیح: البیہقی (10/173)، المعرفة السنن والآثار لہ (5917)۔"}],[1717,"عمرو بن شعیب نے اپنے باپ سے روایت کیا کہ نبی صلی اللہ علیہ وسلم نے گواہی کے متعلق فرمایا: ’’اگر ایک گواہ لایا اور گواہ کے ساتھ قسم بھی کھائی‘‘ (تو کافی ہے۔) (1)","",{"k":"(1) اسنادہ ضعیف لإرسالہ، ولضعف مسلم بن خالد ولعنعنة ابن جریج: البیہقی (10/172)، المعرفة السنن والآثار لہ (5919)۔"}],[1718,"ابو جعفر سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قسم کے ساتھ ایک گواہ پر فیصلہ دیا۔ (1)","",{"k":"(1) اسنادہ ضعیف لإرسالہ الا ان المتن صحیح کما تقدم: البیہقی (10/171)، المعرفة السنن والآثار لہ (5918)۔"}],[1719,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے قسم کے ساتھ ایک گواہ پر فیصلہ دیا۔ (1)","",{"k":"(1) الترمذی (1344)، ابن ماجة (2369)، وصححہ ابن الجارود (1008)۔"}],[1720,"جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے میرے اس منبر پر جھوٹی قسم کھائی اس نے اپنا ٹھکانہ جہنم بنالیا۔‘‘ (1)","",{"k":"(1) ابوداود (3246)، ابن ماجة (2325)، وصححہ ابن الجارود (927)، ابن حبان (4/296)، ووافقہ الذہبی۔","f":"۱۔ جھوٹی قسم کھانا کبیرہ گناہ ہے ایک اعرابی نے نبی صلی اللہ علیہ وسلم سے کبیرہ گناہ سے متعلق دریافت کیا تو آپ نے فرمایا: ’’الا شراک باللہ’’اللہ کے ساتھ شرک کرنا اس نے پھر پوچھا تو آپ نے فرمایا:‘‘عقوق الوالدین’’‘‘والدین کی نافرمانی کرنا۔’’اس نے تیسری دفعہ پوچھا پھر کون سا گناہ کبیرہ ہے۔ تو آپ نے فرمایا:‘‘الیمین الغموس’’‘‘جھوٹی قسم۔‘‘ (صحیح بخاری، کتاب استابة المرتدین ...... باب اثم من اشرک باللہ ...... رقم: ۶۹۲۰)\n۲۔ گناہ کا ارتکاب ہر جگہ ناپسندیدہ ہے لیکن اگر گناہ احترام والی جگہوں مثلاً مساجد وغیرہ میں کیا جائے تو اس کی سنگینی اور زیادہ ہو جاتی ہے۔\n۳۔ نبی صلی اللہ علیہ وسلم نے اپنے منبر کی جگہ سے متعلق ارشاد فرمایا:\n«مابین بیتی ومنبری روضة من ریاض الجنة، ومنبری علی حوضی»\n’’میرے گھر اور میرے منبر کے درمیان کی جگہ جنت کے باغیچوں میں سے ایک باغیچہ ہے اور میرا منبر روز قیامت میرے حوض پر ہوگا۔‘‘ (صحیح بخاری، کتاب فضل الصلاة فی مسجد مکة والمدینة، باب فضل مابین القبر والمنبر، رقم: ۱۱۹۶)\n۴۔ قسم لینا اور کھانا جائز ہے۔ (صحیح مسلم، رقم: ۱۳۹۰)"}],[1721,"ابو غطفان المری نے بیان فرمایا کہ زید بن ثابت رضی اللہ عنہ اور ابن مطیع نے اپنے ایک (مشترکہ) گھر کے جھگڑے کا مقدمہ مروان بن حکم کے سامنے رکھا تو مروان نے اس بات پر فیصلہ دیا کہ زید بن ثابت رضی اللہ عنہ منبر پر قسم کھائیں۔ زید رضی اللہ عنہ نے فرمایا: میں اپنی جگہ پر ہی قسم کھاؤں گا، مروان نے کہا نہیں اللہ کی قسم! وہیں قسم کھاؤ جہاں لوگوں کے فیصلے ہوتے ہیں۔ تو زید رضی اللہ عنہ قسم کھاتے تھے کہ میں سچا ہوں لیکن منبر پر قسم کھانے سے انکار کرتے تھے اور مروان کو اس بات پر تعجب ہوتا تھا۔ امام مالک رحمہ اللہ نے فرمایا، زید رضی اللہ عنہ نے زبردستی قسم لینے کو ناپسند کیا ہے۔ (1)","",{"k":"(1) اسنادہ صحیح: البیہقی (10/177)، المعرفة السنن والآثار لہ (5930)۔","f":"۱۔ معلوم ہوا عہد صحابہ میں مدینہ طیبہ کے اندر اختلافات کے حل کے لیے مسجد نبوی میں منبر کے پاس قسم لی جاتی تھی۔\n۲۔ عہد جاہلیت میں مکہ والے جب کسی سے قسم لیتے تو وہ رکن اور مقام ابراہیم کے درمیان لیتے تھے۔ (بخاری، رقم: ۳۸۴۵)"}],[1722,"ابن ابی ملیکہ نے بیان کیا کہ میں نے ابن عباس رضی اللہ عنہ کو طائف سے دو لونڈیوں کے متعلق لکھا جن میں سے ایک نے دوسری کو مارا تھا اور اس وقت کوئی گواہ بھی نہیں تھا تو انہوں نے میری طرف جواب میں لکھ بھیجا کہ ان کو عصر کے بعد روک اور ان پر یہ آیت پڑھ کہ ’’جو لوگ اللہ کے عہد اور اپنی قسموں کو تھوڑی قیمت پر بیچتے ہیں۔‘‘ (آل عمران: ۷۷) ابن ابی ملیکہ کہتے ہیں میں نے اسی طرح کیا تو ان میں سے ایک نے اقرار (جرم) کرلیا۔ (1)","",{"k":"(1) البخاری (4552)۔","f":"۱۔ مدعی اپنا دعویٰ دلائل اور گواہوں سے ثابت کرتا ہے اگر گواہ موجود نہ ہوں تو پھر مدعی علیہ اپنی صفائی میں قسم دے کر بری ہو جاتا ہے۔\n۲۔ مذکورہ واقعہ میں گواہوں کی عدم موجودگی کی صورت میں چونکہ مدعی علیہ کے ذمہ قسم تھی لہذا اسے پہلے اللہ کی آیت کے ذریعے نصیحت کی گئی تو اعتراف جرم سے معاملہ حل ہو گیا۔\n۳۔ تھوڑے سے دنیوی مفاد کے لیے جھوٹی قسم کھا کر آخرت کو داؤ پر لگا دینا انتہائی بیوقوفی کی علامت ہے۔\n۴۔ جس طرح احترام والی جگہوں میں گناہ انتہائی برا ہے اسی طرح اہم اوقات اور ایام میں بھی گناہ کی سنگینی میں اضافہ ہو جاتا ہے مثلاً رمضان کے مہینے یا عشرہ ذوالحجہ وغیرہ میں گناہ کا ارتکاب کرنا۔\n۵۔ نماز عصر کے بعد کا وقت انتہائی اہم ہے اس وقت جھوٹی قسم کھانا بہت بڑا جرم ہے۔ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے ’’تین افراد سے اللہ تعالیٰ قیامت کے روز نہ کلام کریں گے، نہ ان کی طرف دیکھیں گے، نہ ان کا تزکیہ فرمائیں گے اور ان کے لیے درد ناک عذاب ہے۔ ان تین افراد میں سے ایک شخص وہ ہے جو عصر کے بعد جھوٹی قسم کھا کر سودا سلف بیچتا ہے۔‘‘ (صحیح بخاری، رقم: ۲۶۷۲۔ صحیح مسلم، رقم: ۱۰۸)\n۶۔ بعض مفسرین کے نزدیک والعصر سے مراد بھی عصر کا وقت ہی ہے۔\n۷۔ عصر کے وقت کی اہمیت کا اندازہ درج ذیل حدیث سے بھی لگایا جاسکتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا: «یتعاقبون فیکم ملائکة باللیل وملائکة بالنہار ویجتمعون فی صلاة الفجر وصلاة العصر» (صحیح بخاری، کتاب مواقیت الصلواة، باب فضل العصر، رقم: ۵۵۵) ’’رات اور دن کے فرشتے تمہارے پاس باری باری آتے ہیں اور یہ فجر اور عصر کی نماز میں اکٹھے ہوتے ہیں۔‘‘"}],[1723,"عطاء نے بیان فرمایا کہ میں اور عبید بن عمیر عائشہ رضی اللہ عنہا کے پاس گئے جبکہ وہ شبیر مقام پر اعتکاف بیٹھی ہوئی تھیں۔ میں نے ان سے اللہ کے فرمان کہ ’’اللہ تم پر سے تمہاری لغو قسموں پر مواخذہ نہیں کریں گے۔‘‘ (البقرہ: ۲۲۵) سے متعلق پوچھا تو انہوں نے فرمایا: یہ وہ (قسمیں ہیں جو لوگوں کا تکیہ کلام ہوں جیسے) نہیں اللہ کی قسم! ہاں اللہ کی قسم! (1)","",{"k":"(1) ابوداود (3254)، وصححہ ابن حبان۔"}],[1724,"عائشہ رضی اللہ عنہا نے بیان فرمایا کہ لغو قسم یہ ہے کہ انسان (عادتاً) کہے نہیں اللہ کی قسم! اور ہاں اللہ کی قسم! (1)","",{"k":"(1) البخاری (6663)۔","f":"۱۔ ایسی قسم جو غیر ارادی طور پر عادتاً اٹھائی جائے ’’لغو‘‘ کہلاتی ہے۔\n۲۔ لغو قسم معاف ہے اس پر کفارہ نہیں ہے۔\n۳۔ بات بات پر قسم اٹھانا اچھی عادت نہیں لہذا آدمی کو پرہیز کرتے ہوئے اپنی عادت تبدیل کرنی چاہیے۔"}],[1725,"ابن عمر رضی اللہ عنہما سے روایت ہے انہوں نے فرمایا، جس نے قسم کھائی اور پھر اسے پختہ کر دیا تو (اس کو توڑنے پر) اس پر ایک گردن آزاد کرانا ضروری ہے۔ (1)","",{"k":"(1) صحیح: البیہقی (10/56)، المعرفة السنن والآثار لہ (5814)۔","f":"۱۔ وہ قسم جو انسان اپنی بات میں پختگی پیدا کرنے کے لیے نیت و ارادے سے کھائے اسے اگر توڑے گا تو اس پر کفارہ لازم آئے گا۔\n۲۔ کفارہ قسم سے متعلق ارشاد باری تعالیٰ ہے: ﴿لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الْأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَشْكُرُونَ﴾ (المائدة: ۸۹) ’’اللہ تعالیٰ تم پر تمہاری لغو قسموں میں مواخذہ نہیں کریں گے، البتہ ان قسموں پر جو تم نے قصداً کھائی ہیں مواخذہ کریں گے۔ اس کا کفارہ دس مسکینوں کو اوسط درجے کا کھانا کھلانا ہے جو تم اپنے گھر والوں کو کھلاتے ہو یا انہیں کپڑے دینا ہے، یا ایک غلام آزاد کرنا ہے اور جس کی استطاعت نہ ہو تو (اس کے لیے مسلسل) تین روزے رکھنے ہیں یہ تمہاری قسموں کا کفارہ ہے جب تم قسم کھاؤ (پھر توڑ دو) اور اپنی قسموں کی حفاظت کرو، اسی طرح اللہ تمہارے لیے اپنے احکام بیان فرماتا ہے تا کہ تم شکر کرو۔‘‘"}],[1726,"ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں ہمیشہ لوگوں سے لڑتا رہوں گا یہاں تک کہ وہ اقرار کرلیں کہ اللہ کے علاوہ کوئی معبود نہیں ہے، جب انہوں نے اس کا اقرار کرلیا تو انہوں نے ہم سے اپنا خون اور اپنا مال محفوظ کرلیا سوائے اس کے حق کے اور ان کا حساب اللہ کے ذمہ ہے۔‘‘ (1)","",{"k":"(1) البخاری (2946)، مسلم (21)۔"}],[1727,"ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں ہمیشہ لوگوں سے لڑتا رہوں گا یہاں تک کہ وہ اقرار کرلیں کہ اللہ کے سوا کوئی معبود نہیں، جب وہ اس کا اقرار کرلیں تو انہوں نے مجھ سے اپنے خون اور مال محفوظ کر لیے سوائے اس کے حق کے، اور ان کا حساب اللہ تعالیٰ کے ذمہ ہے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1726)","f":"۱۔ جہاد فی سبیل اللہ کا بنیادی مقصد توحید وسنت کی اشاعت اور اعلاء کلمة اللہ یعنی غلبہ دین ہے۔\n۲۔ کلمہ توحید کا اقرار کرنے والے کو مسلمان سمجھا جائے گا اور اس پر مسلمانوں کے احکامات جاری ہوں گے۔\n۳۔ خون اور مال کے محفوظ ہونے کا مطلب یہ ہے کہ کلمہ پڑھنے والے سے قتال نہیں کیا جائے گا اور نہ اس کے مال کو بطور غنیمت لیا جائے گا۔\n۴۔ ’’الا بحقھا‘‘ سے مراد وہ جرائم ہیں جن کی وجہ سے کسی مسلمان کا خون بہانا جائز ہے یعنی قتل کی صورت میں قصاصاً قتل کرنا، شادی شدہ زانی کو سنگسار کرنا اور ارتداد اختیار کرنے والے کو قتل کر دینا۔\n۵۔ شرعی احکام ظاہر پر نافذ ہوتے ہیں باطن کا معاملہ اللہ کے سپرد ہے۔\n۶۔ اگر کسی کو دنیا میں سزا نہ مل سکے تو اس کا معاملہ اللہ کے سپرد ہے روزِ قیامت اللہ چاہیں تو اسے معاف فرما دیں یا اسے گناہ کی سزا دیں۔\n۷۔ توحید اور اعلائے کلمة اللہ کے علاوہ کسی اور مقصد کے لیے لڑنا اور اسے جہاد کا نام دینا درست نہیں۔\n۸۔ جہاد ایک عظیم عبادت اور انتہائی افضل عمل ہے کہ نبی علیہ السلام نے اپنی حیات طیبہ میں تقریباً ستائیس یا اٹھائیس غزوات میں شرکت فرمائی چھہتر کے قریب مجاہدین کے مختلف مقامات پر فوجی دستے روانہ کیے۔"}],[1728,"ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب کسریٰ مر جائے گا تو اس کے بعد کوئی کسریٰ پیدا نہ ہوگا، اور جب قیصر مر جائے گا تو اس کے بعد کوئی قیصر پیدا نہ ہوگا، مجھے اس ذات کی قسم! جس کے ہاتھ میں میری جان ہے۔ تم ان دونوں (قیصر وکسریٰ) کے خزانے اللہ کے راستے میں خرچ کرو گے۔‘‘ (1)","",{"k":"(1) البخاری (3618)، مسلم (2918)۔","f":"۱۔ عہد رسالت میں دو بڑی حکومتیں تھیں ایک ایران اور دوسری روم، ایرانی آتش پرست تھے اور رومی عیسائی تھے۔ ایرانی فرمانروا، ’’کسریٰ’’کے لقب سے مشہور تھا اور روم کا بادشاہ‘‘قیصر‘‘ کہلاتا تھا۔\n۲۔ روم و ایران کی فتح سے متعلق یہ رسول اللہ صلی اللہ علیہ وسلم کی پیشین گوئی تھی جو امیر المومنین سیدنا عمر بن خطاب رضی اللہ عنہ کے عہد میں پوری ہوئی اور مسلمانوں نے روم و ایران کی عظیم الشان سلطنتوں کو فتح کیا، قیصر و کسریٰ کو ہزیمت کا سامنا کرنا پڑا اور پھر ان کی موت کے بعد ان کا کوئی بھی جانشین پیدا نہ ہوسکا۔\n۳۔ نبی علیہ السلام نے صلح حدیبیہ کے بعد مختلف بادشاہوں اور امراء کے نام اسلام کی دعوت کے خطوط روانہ کیے ان میں سے دو خط آپ نے روم و ایران کے بادشاہوں کے نام بھی لکھے۔ سیدنا عبداللہ بن حذافہ رضی اللہ عنہ کو شاہ فارس خسرو پرویز کے نام خط دے کر بھیجا تو اس نے خط سن کر چاک کر دیا جبکہ شاہ روم قیصر کے نام لکھے گئے خط کو دحیہ کلبی رضی اللہ عنہ لے کر گئے۔\n۴۔ مذکورہ حدیث سے معلوم ہوا مسلمانوں کے لیے مال غنیمت حلال ہے۔\n۵۔ ’’والذی نفسی بیدہ‘‘ کے الفاظ سے قسم کھانا جائز ہے۔"}],[1729,"ابن عباس رضی اللہ عنہ سے روایت ہے فرمایا کہ جب یہ آیت نازل ہوئی: ’’اگر تم میں بیس آدمی صبر کرنے والے ہوں تو وہ دو سو پر غالب آجائیں گے’’تو مسلمانوں پر فرض کر دیا گیا کہ بیس آدمی دو سو کے مقابلے سے نہ بھاگیں۔ پھر اللہ تعالیٰ نے نازل فرمایا:‘‘اب اللہ نے تم سے تخفیف کردی، اور معلوم کر لیا کہ تم میں جوش کی کمی ہے، پس اگر اب تم میں سو صبر کرنے والے ہوں تو وہ دو سو پر غالب آجائیں گے۔‘‘ تو اللہ نے ان سے تخفیف کر دی اور ان پر یہ فرض کر دیا کہ سو (مسلمان) دو سو (کفار) کے مقابلے سے نہ بھاگیں۔ (1)","",{"k":"(1) البخاری (4652)۔","f":"۱۔ پہلا حکم صحابہ کرام رضی اللہ عنہم پر گراں گزرا کہ ایک مسلمان دس کفار اور دس مسلمان ایک سو کفار کے لیے کافی ہیں اور اگر مسلمانوں کی اتنی تعداد ہو تو ان پر جہاد فرض ہے پھر اللہ تعالیٰ نے اس میں تخفیف فرما کر ایک اور دو کا تناسب کر دیا۔\n۲۔ میدان جہاد سے فرار اختیار کرنا کبیرہ گناہ ہے۔ ارشاد باری تعالیٰ ہے: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا لَقِيتُمُ الَّذِينَ كَفَرُوا زَحْفًا فَلَا تُوَلُّوهُمُ الْأَدْبَارَ وَمَنْ يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُ إِلَّا مُتَحَرِّفًا لِقِتَالٍ أَوْ مُتَحَيِّزًا إِلَى فِئَةٍ فَقَدْ بَاءَ بِغَضَبٍ مِنَ اللَّهِ وَمَأْوَاهُ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ﴾ (الانفال: ۱۵ - ۱۶) ’’اے ایمان والو! جب تم کفار سے ایک دوسرے کے مقابل ہو جاؤ تو ان سے پیٹھ مت پھیرنا اور جو شخص ان سے اس وقت پیٹھ پھیرے گا سوائے اس کے جو لڑائی کے لیے پینترا بدلتا ہو یا اپنی جماعت کی طرف پناہ لینے آتا ہو۔ (ان کے علاوہ جو ایسا کرے) وہ اللہ کے غضب کے ساتھ لوٹا اور اس کا ٹھکانہ جہنم ہے جو بہت بری جگہ ہے۔’’سیدنا ابو ہریرہ رضی اللہ عنہ بیان فرماتے ہیں نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا:‘‘اجتنبوا السبع الموبقات’’سات ہلاک کرنے والے کاموں سے بچو۔ ان سات کو شمار کرتے ہوئے آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘والتولى يوم الزحف‘‘ اور مقابلے والے دن پیٹھ پھیرنا۔ (بخاری، کتاب الوصایا، باب قول اللہ ان الذین یاکلون اموال الیتمی ...... الخ، رقم: ۲۷۶۶)"}],[1730,"ابن عباس رضی اللہ عنہ نے بیان فرمایا کہ جو (مسلمان) تین (کفار) کے مقابلے سے بھاگ نکلا تو وہ (حقیقت میں) نہیں بھاگا اور جو دو کے مقابلے سے بھاگ گیا وہ (حقیقتاً) بھاگ گیا۔ (1)","",{"k":"(1) اسنادہ ضعیف لانقطاعہ فان ابن ابی نجیح لم یلق احدا من الصحابة واخرجہ البیہقی فی المعرفة السنن والآثار (5382)۔ وفی الکبری لہ: 9/ 76۔ والطبرانی فی الکبیر: 11/ 76 (1151) مرفوعًا."}],[1731,"ابن عمر رضی اللہ عنہ نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک سریہ (جنگ) میں بھیجا، دشمن سے مقابلہ ہوا تو لوگ بھاگ کھڑے ہوئے، ہم مدینہ آئے تو ہم نے اس کے دروازوں کو کھول دیا اور ہم نے کہا اے اللہ کے رسول اللہ آپ پر رحمت بھیجے ہم تو (میدانِ جنگ سے) بھاگنے والے ہیں تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’(نہیں) بلکہ تم تو اپنے امام کے پاس آکر پناہ لینے والے ہو اور میں مسلمانوں کی جائے پناہ ہوں۔‘‘ (1)","",{"k":"(1) اسنادہ ضعیف لضعیف یزید بن ابی زیاد اخرجہ ابوداود (2647)۔ والترمذی (1716)"}],[1732,"بریدہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب کوئی لشکر بھیجتے تو اس پر امیر مقرر کرتے اور فرماتے: ’’جب تم اپنے مشرک دشمنوں سے (میدانِ جنگ میں) ملو تو انہیں تین باتوں یا تین خصلتوں۔ علقمہ رضی اللہ عنہ کو ان الفاظ میں شک ہوا ہے۔ کو ماننے کی دعوت دو (سب سے پہلے) انہیں اسلام قبول کرنے کی دعوت دو اگر وہ آپ کی دعوت قبول کر لیں تو ان سے (اسلام) منظور کرلو، اور ان سے (اپنی تلوار) روک لو، پھر انہیں (اگر دعوتِ اسلام قبول کریں تو) اپنا وطن چھوڑ کر جہاں مہاجرین رہتے ہیں وہاں آنے کی دعوت دو اور انہیں بتاؤ اگر وہ ہجرت کریں گے تو ان کے لیے وہی فوائد ہیں جو مہاجرین کے لیے ہیں اور ان پر وہی فرائض ہوں گے جو مہاجرین پر ہیں۔ اگر وہ اپنی جگہ ہی رہنا چاہیں تو وہ دیہاتی مسلمانوں کی طرح ہوں گے، ان پر بھی اللہ کا حکم اسی طرح جاری ہوگا جیسے دوسرے مسلمانوں پر ہوتا ہے اور ان کے لیے مال فئے میں کچھ نہیں ہے مگر یہ کہ وہ مسلمانوں کے ساتھ جہاد کریں (تو پھر انہیں غنیمت اور فی سے حصہ ملے گا) اگر وہ اس بات کو ماننے سے انکار کر دیں تو ان کو کہو کہ وہ ذلیل وخوار ہو کر اپنے ہاتھ سے جزیہ ادا کریں۔ اگر وہ یہ کام کر لیں تو ان سے (جزیہ) قبول کر کے انہیں چھوڑ دو، اور اگر وہ اس سے بھی انکار کر دیں تو اللہ سے مدد مانگو اور ان سے قتال کرو۔‘‘ (1)","",{"k":"(1) مسلم (1731)۔"}],[1733,"بریدہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب کوئی لشکر بھیجتے تو ان پر امیر مقرر کرتے ...... آگے لمبی حدیث بیان فرمائی۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1732)","f":"۱۔ قتال سے پہلے میدان میں دعوت سے متعلق شروع اسلام میں حکم تھا بعد میں نبی علیہ السلام نے ان قوموں سے جنہیں پہلے دعوت اسلام پہنچ چکی تھی میدان میں انہیں دعوت دیے بغیر قتال کیا۔ دیکھئے حدیث نمبر: ۱۷۴۱۔\n۲۔ جہاد اور قتال کا بنیادی مقصد اسلام کی ترویج و تغلیب ہے۔\n۳۔ مسلمان کفار کے ممالک میں رہیں یا اسلامی مملکتوں میں شرعی احکامات کی ادائیگی ان پر ہر حال میں لازم ہے۔\n۴۔ ہجرت کرنے والوں اور دارالکفر سے ہجرت نہ کرنے والے مسلمانوں میں بعض مسائل مختلف ہیں۔\n۵۔ اسلامی حکومت میں رہنے والے غیر مسلموں سے ان کے جانی و مالی تحفظ کے عوض وصول کیا جانے والا ٹیکس جزیہ کہلاتا ہے۔\n۶۔ کفار کی طرف سے جزیہ کی ادائیگی گویا ایک طرح کی ان سے جزیہ کے عوض صلح ہے۔\n۷۔ عرب و عجم کے تمام کفار اہل کتاب و غیر اہل کتاب سے جزیہ لینا درست ہے۔\n۸۔ امیر و حکمران کو چاہیے کہ جب جہادی قافلوں کو روانہ کرے تو انہیں بعض اہم امور سے متعلق ضروری ہدایات دے۔"}],[1734,"ابن کعب بن مالک نے اپنے چچا سے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے جنہیں ابن ابی حقیق کی طرف بھیجا تھا انہیں عورتوں اور بچوں کو قتل کرنے سے منع کیا تھا۔ (1)","",{"k":"(1) صحیح: البیہقی (9/78)، المعرفة السنن والآثار لہ (5393)، ابن ابی شیبة (33115)، الحمیدی (874)۔"}],[1735,"ابن کعب بن مالک نے اپنے چچا سے روایت کیا کہ نبی صلی اللہ علیہ وسلم نے جب ابن ابی حقیق کی طرف (لشکر) بھیجا تو انہیں عورتوں اور بچوں کو قتل کرنے سے منع فرمایا۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (1734)","f":"معلوم ہوا دورانِ جنگ عورتوں اور بچوں کو قتل کرنا درست نہیں۔ لیکن اگر عورتیں لڑائی میں حصہ لیں تو انہیں قتل کرنا جائز ہے۔"}],[1736,"ابن عباس رضی اللہ عنہ نے بیان فرمایا کہ مجھے صعب بن جثامہ رضی اللہ عنہ نے بتایا کہ انہوں نے نبی صلی اللہ علیہ وسلم سے سنا کہ آپ صلی اللہ علیہ وسلم سے پوچھا گیا کہ مشرکین کے گھر والوں کا کیا حکم ہے جبکہ ان پر شب خون مارا جاتا ہے تو چھوٹے بچے اور عورتیں بھی اس کی زد میں آجاتے ہیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ انہیں میں سے ہیں۔’’عمرو بن دینار نے زہری سے یہ الفاظ زیادہ بیان کیے کہ‘‘وہ اپنے باپ دادوں میں سے ہیں۔‘‘ (یعنی اسی نسل سے تعلق رکھتے ہیں۔) (1)","",{"k":"(1) البخاری (3012، 3013)، مسلم (1745)۔"}],[1737,"صعب بن جثامہ اللیثی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے پوچھا گیا کہ مشرکین کے گھر والوں کا کیا حکم ہے جبکہ شب خون مارا جاتا ہے تو چھوٹے بچے اور عورتیں بھی اس کی زد میں آجاتے ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا: ’’وہ انہیں میں سے ہیں۔’’بعض اوقات سفیان رحمہ اللہ نے حدیث میں یہ الفاظ بیان کیے ہیں کہ‘‘وہ اپنے آباء میں سے ہیں۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم: (1736)","f":"۱۔ عورتوں اور بچوں کو قصداً قتل کرنا درست نہیں دیکھئے حدیث سابق۔\n۲۔ وہ عورتیں اور بچے جو اپنی قوم کی طرف سے میدانِ جنگ میں آئیں اور معرکہ آرائی میں حصہ لیں ان کو قتل کرنا درست ہے۔\n۳۔ کفار پر شب خون مارتے وقت اگر عورتیں اور بچے زد میں آ کر قتل ہو جائیں تو ان کی معافی ہے۔"}],[1738,"سیدنا انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ عمر بن خطاب رضی اللہ عنہ نے ان سے پوچھا: جب تم شہر کا محاصرہ کرلو تو تم کیا کرو گے؟ انہوں نے جواب دیا: ہم ایک آدمی کو چمڑے کا لباس پہنا کر شہر کی طرف بھیجیں گے۔ آپ رضی اللہ عنہ نے فرمایا: تمہارا کیا خیال ہے؟ اگر اسے کوئی پتھر مار دے تو؟ انہوں نے کہا: تب وہ قتل ہو جائے گا تو عمر رضی اللہ عنہ نے فرمایا: پھر تم اس طرح نہ کرو۔ اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! مجھے پسند نہیں کہ تم ایک مسلمان کے ضیاع کے بدلے میں ایک ایسا شہر فتح کرو جس میں چار ہزار لڑنے والے آدمی ہوں۔ (1)","",{"k":"(1) اسنادہ ضعیف، لعنعنة حمید بن ابی حمید الطویل: البیہقی (9/42)، المعرفة السنن والآثار لہ (5326)۔"}],[1739,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے تستر قلعے کا محاصرہ کیا، ہرمزان عمر رضی اللہ عنہ کے حکم پر اترا تو میں اسے عمر رضی اللہ عنہ کے پاس لے کر آیا تو آپ رضی اللہ عنہ نے اس سے فرمایا: بات کرو، اس نے کہا: زندہ (یعنی دلیر) آدمی کی (طرح بات کروں) یا مردہ (یعنی بزدل) آدمی کی (طرح)؟ عمر رضی اللہ عنہ نے فرمایا: بات کرو تمہیں کوئی اندیشہ نہیں ہے (یعنی جو کچھ کہنا چاہتے ہو بلا خوف وخطر کہو)۔ وہ کہنے لگا: ہم اور آپ عرب کے باشندے ہیں مگر اللہ نے ہمارے اور تمہارے درمیان فرق رکھا ہے ہم تمہیں غلام بنایا کرتے تھے اور تمہیں قتل کیا کرتے اور تمہارا مال غصب کر لیا کرتے تھے، جب اللہ تمہارے ساتھ ہو گیا تو ہم کمزور ہو گئے۔ عمر رضی اللہ عنہ نے مجھ سے فرمایا: تم کیا کہتے ہو؟ میں نے کہا: اے امیر المومنین! میں نے اپنے بعد بہت زیادہ دشمن اور طاقت چھوڑی ہے، اگر آپ ان کو بھی قتل کر دیں گے تو لوگ زندگی سے ناامید ہو جائیں گے اور اس طرح آپ کی طاقت بھی بڑھ جائے گی۔ عمر رضی اللہ عنہ نے فرمایا: شرم کرو، براء بن مالک اور مجزأہ بن ثور نے لڑائی کی جب تم اس کے قتل کیے جانے سے ڈرے تو تم کہنے لگے: اس کے قتل کی کوئی گنجائش نہیں، میں نے تو اسے کہا ہے بات کرو تمہیں کوئی اندیشہ نہیں ہے، پھر عمر رضی اللہ عنہ نے فرمایا: تم نے اس سے رشوت یا کوئی اور چیز لی ہے؟ میں نے کہا: اللہ کی قسم! نہ میں نے اس سے نہ رشوت لی ہے اور نہ ہی کوئی اور چیز تو عمر رضی اللہ عنہ نے فرمایا: جو تم نے گواہی دی ہے اس پر اپنے علاوہ کوئی اور آدمی بھی پیش کرو یا پھر تمہیں سزا ملے گی، میں وہاں سے نکلا تو مجھے زبیر بن عوام ملے تو انہوں نے بھی میرے ساتھ گواہی دی، عمر رضی اللہ عنہ نے اسے قتل نہ کیا، وہ بھی بعد میں مسلمان ہو گیا تو عمر رضی اللہ عنہ نے اس کی تنخواہ مقرر کر دی۔ (1)","",{"k":"(1) البیہقی (9/96)، المعرفة السنن والآثار لہ (5428)، ابن ابی شیبة (33402)۔"}],[1740,"انس رضی اللہ عنہ سے روایت ہے انہوں نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم رات کو خیبر پہنچے اور رسول اللہ صلی اللہ علیہ وسلم جب رات کو کسی قوم کے پاس آتے (حملہ کے لیے) تو صبح سے پہلے ان پر حملہ نہیں کرتے تھے۔ اگر اذان سن لیتے تو حملہ نہ کرتے اور اگر وہ نماز نہ پڑھنے والے ہوتے تو صبح کے وقت ان پر حملہ کر دیتے۔ جب صبح ہوئی تو آپ صلی اللہ علیہ وسلم بھی سوار ہوئے اور مسلمان بھی سوار ہو گئے۔ اور بستی والے (اس حال میں) نکلے کہ ان کے پاس ان کی ٹوکریاں اور کدالیں تھیں۔ جب انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا تو کہا، محمد (صلی اللہ علیہ وسلم) اور (ان کا) لشکر۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ اکبر، خیبر خراب ہوا، جب ہم کسی قوم کے پاس پہنچتے ہیں تو ان لوگوں کی صبح بری ہوتی ہے۔ جنہیں (عذاب سے) ڈرایا گیا ہے۔‘‘ انس رضی اللہ عنہ نے فرمایا میں ابو طلحہ رضی اللہ عنہ کے پیچھے سوار تھا کہ میرا قدم رسول اللہ صلی اللہ علیہ وسلم کے قدم مبارک کو چھو رہا تھا۔ (1)","",{"k":"(1) البخاری (2943، 371)۔","f":"۱۔ جن کفار کو دعوت اسلام پہنچ چکی ہو انہیں میدان جنگ میں دوبارہ دعوت دینا ضروری نہیں ہے مزید تفصیل کے لیے دیکھیے فوائد حدیث نمبر: ۴۳۲، ۴۳۳۔ ۲۔ دشمن کی غفلت سے فائدہ اٹھاتے ہوئے ان پر حملہ آور ہونا درست ہے ۳۔ جو کفار اسلام اور مسلمانوں کے خلاف سازشیں کریں ان کے خلاف اقدامی جہاد درست ہے ۴۔ صبح کے وقت حملہ کرنا بہتر ہے۔ ۵۔ اذان شعائر اسلام میں سے ہے جس بستی میں اذان ہو اس پر شب خون مارنا جائز نہیں۔ ۶۔ خمیس لشکر کو اس لیے کہتے ہیں کہ اس کے پانچ حصے ہوتے ہیں۔ ۱۔ مقدمہ۔ ۲۔ ساقہ۔ ۳۔ میمنہ۔ ۴۔ میسرہ۔ ۵۔ قلب۔ ۷۔ میدان جہاد میں نعرہ تکبیر بلند کرنا مسنون ہے۔ ۸۔ خیبر کی بستی مدینہ منورہ سے تقریباً ۱۷۵ کلومیٹر کے فاصلے پر شمال میں واقع ہے۔ ۹۔ غزوہ خیبر یہودیوں کے خلاف محرم الحرام ۷ ہجری میں ہوا۔ ۱۰۔ ام المومنین سیدہ صفیہ بنت حیی بن اخطب رضی اللہ عنہا اسی غزوہ میں قید ہوئیں بعد میں ان کے اسلام قبول کرنے پر نبی صلی اللہ علیہ وسلم نے ان کو آزاد فرما کر ان سے نکاح کر لیا۔"}],[1741,"عبداللہ بن عون سے روایت ہے کہ نافع رضی اللہ عنہ نے ان کی طرف لکھا اور اسے بتایا کہ ابن عمر رضی اللہ عنہ نے خبر دی کہ نبی صلی اللہ علیہ وسلم نے جب بنو مصطلق پر حملہ کیا تو وہ بالکل غافل اپنے جانوروں کے ساتھ مریسیع کے مقام پر تھے۔ ان کے لڑنے والوں کو قتل کر دیا اور عورتوں، بچوں کو قیدی بنا لیا۔ (1)","",{"k":"(1) البخاری (2541)، مسلم (1730)۔","f":"۱۔ عبداللہ بن عون نے سیدنا نافع رضی اللہ عنہ سے میدان جنگ میں قتال سے قبل کفار کو دعوت دینے سے متعلق دریافت کیا تو نافع رضی اللہ عنہ نے انہیں یہ حدیث لکھ کر بھیجی۔ (دیکھیے صحیح مسلم، رقم: ۱۷۳۰) ۲۔ دشمن کی غفلت سے فائدہ اٹھا کر ان پر حملہ کر دینا بہترین جنگی تدبیر ہے۔ ۳۔ مریسیع ایک کنویں کا نام ہے جہاں حملے کے وقت بنو مصطلق اپنے اونٹوں کو پانی پلا رہے تھے۔ ۴۔ غزوہ بنی مصطلق کا دوسرا نام غزوہ مریسیع بھی ہے اور یہ غزوہ ۵ یا ۶ ہجری کو شعبان کے مہینے میں ہوا۔ ۵۔ واقعہ افک اسی غزوہ سے واپسی پر پیش آیا تھا۔ (دیکھیے بخاری، رقم: ۴۱۴۱)"}],[1742,"ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بنو نضیر کے مالوں کو جلا دیا تھا۔ (1)","",{"k":"(1) انظر الحدیث الآتی برقم (1743)","f":"۱۔ مدینہ طیبہ کے اطراف میں یہودیوں کے تین قبیلے بنو نضیر، بنو قینقاع اور بنو قریظہ آباد تھے، نبی صلی اللہ علیہ وسلم نے ہجرت مدینہ کے بعد ان سے دفاعی معاہدہ کیا، لیکن یہ لوگ ہمیشہ در پردہ سازشیں کرتے رہے حتی کہ ایک دفعہ بنو نضیر نے رسول اللہ صلی اللہ علیہ وسلم کو شہید کرنے کی سازش بھی کی، اس عہد شکنی کی وجہ سے آپ نے ان پر لشکر کشی کی، یہ لوگ کچھ عرصہ اپنے قلعوں میں محصور رہے پھر انہوں نے جلا وطنی پر آمادگی ظاہر کی جسے رسول اللہ صلی اللہ علیہ وسلم نے قبول فرما لیا۔ ۲۔ مسلمانوں نے دوران محاصرہ نبی صلی اللہ علیہ وسلم کے حکم سے بنو نضیر کے درختوں کو آگ لگائی جس سے معلوم ہوا جنگی ضرورت کے تحت دشمن کے درختوں کو آگ لگانا یا ان کے گھروں کو گرانا جائز ہے۔ ۳۔ بنو نضیر کی تباہی و بربادی کا اللہ تعالیٰ نے قرآن میں بھی تفصیل سے نقشہ بیان فرمایا ہے۔ دیکھیے سورة حشر: ۱ تا ۷۔ ۴۔ بنو نضیر کے خلاف رسول اللہ صلی اللہ علیہ وسلم نے ربیع الاول ۴ ہجری میں لشکر کشی کی تھی۔"}],[1743,"ابن شہاب سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بنو نضیر کے مالوں کو جلوا دیا، تو کہنے والے نے کہا: بنو لؤی (یعنی قریش) کے سرداروں کے نزدیک بویرہ کے باغات میں چاروں طرف پھیلی ہوئی آگ ایک معمولی واقعہ ثابت ہوئی۔ (1)","",{"k":"(1) صحیح ثبت موصولاً: البخاری (2326)، مسلم (1746)۔","f":"۱۔ مذکورہ شعر سیدنا حسان بن ثابت رضی اللہ عنہ کا ہے۔ (دیکھیے صحیح بخاری، رقم: ۲۳۲۶) ۲۔ بنو نضیر کے کھجوروں کے باغات جس جگہ پر واقع تھے اس کو ’’بویرہ‘‘ کہا جاتا تھا۔"}],[1744,"ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے بنو نضیر کی کھجوروں (کے باغات) کو کٹوا کر ان کو آگ لگا دی اور وہ (باغات) بویرہ جگہ میں تھے۔ (1)","",{"k":"(1) انظر الحدیث الذی قبلہ برقم (1743)"}],[1745,"ابن شہاب سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بنو نضیر کے مالوں کو جلوا دیا تو کہنے والے نے کہا: بنو لؤی (یعنی قریش) کے سرداروں پر بویرہ کے باغات میں چاروں طرف سے پھیلی ہوئی آگ ایک معمولی واقعہ ثابت ہوئی۔ (1)","",{"k":"(1) تقدم تخریجہ برقم (1743)"}],[1746,"اسامہ بن زید رضی اللہ عنہ نے بیان فرمایا کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ میں صبح کے وقت ’’أُبْنَى‘‘ کے علاقے پر حملہ کروں اور ان (کے ساز و سامان) کو جلا دوں۔ (1)","",{"k":"(1) اسنادہ ضعیف: ابوداود (2616)، ابن ماجة (2843)۔"}],[1747,"ابو قتادہ رضی اللہ عنہ انصاری نے بیان فرمایا کہ ہم غزوہ حنین کے سال رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے، جب ہم دشمن سے ملے تو ابتداء میں مسلمان ڈگمگانے لگے کہ میں نے مشرکوں میں سے ایک آدمی کو دیکھا جو ایک مسلمان پر غالب ہو چکا تھا، میں جلدی سے اس کی طرف مڑا یہاں تک کہ میں نے اس کے پیچھے سے آ کر اس کی گردن پر تلوار دے ماری، پھر وہ میری طرف مڑا اور مجھے اس قدر زور سے بھینچا کہ مجھے موت کا خدشہ محسوس ہوا، پھر اس کو موت نے آ لیا تب اس نے مجھے چھوڑا۔ پھر میں عمر بن خطاب رضی اللہ عنہ سے بعد میں ملا تو میں نے ان سے پوچھا، اب لوگوں کا کیا حال ہے؟ انہوں نے کہا جو اللہ کا حکم تھا وہ ہوا۔ پھر لوگ (یعنی مسلمان) جنگ میں واپس آ گئے (یعنی سنبھل گئے) تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے کسی کافر کو قتل کیا اور اس پر گواہی ہو تو اس (مقتول کافر) کا سارا ساز و سامان اسے ملے گا۔‘‘ (ابو قتادہ کہتے ہیں) میں کھڑا ہوا اور میں نے کہا، میری طرف سے کون گواہی دے گا؟ پھر میں بیٹھ گیا، آپ صلی اللہ علیہ وسلم نے یہی بات دوبارہ کہی تو میں نے کھڑے ہو کر کہا، میری طرف سے کون گواہی دے گا؟ (کسی نے گواہی نہ دی) تو میں پھر بیٹھ گیا آپ صلی اللہ علیہ وسلم نے تیسری بار یہی بات دہرائی تو میں تیسری بار کھڑا ہو گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اے ابو قتادہ کیا ہے؟‘‘ پھر میں نے آپ صلی اللہ علیہ وسلم کے سامنے سارا واقعہ بیان کیا تو قوم سے ایک آدمی نے کہا، اے اللہ کے رسول صلی اللہ علیہ وسلم! اس نے سچ کہا، اور اس مقتول کا سامان میرے پاس ہے، اور آپ میرے حق میں انہیں راضی کر دیں۔ لیکن ابوبکر رضی اللہ عنہ نے فرمایا، نہیں، اللہ کی قسم! ہم اللہ کے شیروں میں سے ایک شیر کے ساتھ ایسا نہیں کریں گے کہ وہ اللہ تعالیٰ کے لیے لڑے اور ہم ان کا مال تمہیں دے دیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ابوبکر نے سچ کہا،‘‘ پھر آپ صلی اللہ علیہ وسلم نے وہ سامان انہیں دے دیا۔ ابو قتادہ رضی اللہ عنہ نے کہا آپ صلی اللہ علیہ وسلم نے وہ مجھے وہ سامان دیا تو میں نے زرہ بیچی اور بنو سلمہ میں ایک باغ خریدا، اور یہ وہ پہلا مال تھا جو اسلام لانے کے بعد میں نے حاصل کیا۔ امام مالک رحمہ اللہ نے فرمایا: مخرف کا مطلب ہے نخل (کھجور)۔ (1)","",{"k":"(1) البخاری (2100، 3142)، مسلم (1751)۔","f":"۱۔ غزوہ حنین میں ابتدائی طور پر دشمن غالب آیا اور مسلمانوں کو ہزیمت کا سامنا کرنا پڑا پھر مسلمان متحد ہو کر پوری قوت سے لڑے تو اللہ تعالیٰ نے مسلمانوں کو فتح و نصرت سے نواز دیا اس واقعہ کا ذکر کرتے ہوئے اللہ تعالیٰ ارشاد فرماتے ہیں:\n﴿ لَقَدْ نَصَرَكُمُ اللَّهُ فِي مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنْكُمْ شَيْئًا وَضَاقَتْ عَلَيْكُمُ الْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُمْ مُدْبِرِينَ ○ ثُمَّ أَنْزَلَ اللَّهُ سَكِينَتَهُ عَلَى رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ وَأَنْزَلَ جُنُودًا لَمْ تَرَوْهَا وَعَذَّبَ الَّذِينَ كَفَرُوا وَذَلِكَ جَزَاءُ الْكَافِرِينَ○ ﴾ [التوبة: ۲۵۔ ۲۶]\n’’یقیناً اللہ تعالیٰ نے بہت سے میدانوں میں تمہاری مدد فرمائی اور حنین کی لڑائی والے دن بھی جب تم اپنی کثرت پر نازاں ہوئے، لیکن اس (کثرت) نے تمہیں کچھ فائدہ نہ دیا اور زمین تم پر فراخی کے باوجود تنگ ہو گئی اور تم پیٹھ پھیر کر پیچھے مڑ گئے، پھر اللہ تعالیٰ نے اپنی طرف سے اپنے نبی اور مومنوں پر تسکین اتاری، اور اپنے لشکر بھیجے جنہیں تم نہیں دیکھ رہے تھے اور کافروں کو سزا دی اور کافروں کا یہی بدلہ ہے۔‘‘ ۲۔ جو شخص کسی جنگ میں کافر کو قتل کرے تو اس کا کافر کا ذاتی سامان قاتل کو ملے گا۔ ۳۔ معلوم ہوا اسلحہ بیچنا جائز ہے۔ ۴۔ غزوہ حنین فتح مکہ کے فوراً بعد ۸ ہجری کو شوال میں ہوا۔"}],[1748,"سائب بن یزید سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے غزوہ احد کے دن دو زرہیں اوپر تلے پہنیں۔ (1)","",{"k":"(1) صحیح: ابن ماجة (2806)، النسائی فی الکبری (8583)۔","f":"۱۔ میدان جنگ میں اپنے بچاؤ کے لیے حفاظت تدابیر اختیار کرنا مشروع ہے اور یہ توکل علی اللہ کے منافی نہیں۔ ۲۔ کفار کے خلاف لڑائی اور دشمن کے ہتھیاروں سے بچاؤ کے لیے نبی صلی اللہ علیہ وسلم نے اس وقت کے لحاظ سے اشیاء مثلاً تلوار، ڈھال، خود اور زرہ وغیرہ استعمال کیں اور اب سائنسی دور میں ٹینک، مشین گن، بکتر بند گاڑیاں وغیرہ کا استعمال شرعی تقاضا ہے۔"}],[1749,"ابن عمر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے (مال غنیمت سے) گھوڑے کے لیے دو حصے اور اس کے مالک کے لیے ایک حصہ مقرر فرمایا۔ (1)","",{"k":"(1) البخاری (2863)، مسلم (1762)۔","f":"۱۔ دشمن سے میدان جنگ میں حاصل ہونے والے مال کو مال غنیمت کہتے ہیں۔ ۲۔ مجاہدین کو جو مال بطور غنیمت حاصل ہوا اس کے چار حصے لشکر میں تقسیم ہوں گے جبکہ پانچواں حصہ حاکم وقت اپنی صوابدید پر مختلف مصارف میں خرچ کرے گا ارشاد باری تعالیٰ ہے:\n﴿ وَاعْلَمُوا أَنَّمَا غَنِمْتُمْ مِنْ شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَى وَالْيَتَمَى وَالْمَسَكِينِ وَابْنِ السَّبِيلِ ﴾ [الانفال: ۴۱]\n’’اور تم جان لو! کہ جو کچھ تم غنیمت حاصل کرو اس کا پانچواں حصہ اللہ تعالیٰ کا ہے اور رسول کا اور قرابت داروں کا اور یتیموں کا اور مسکینوں کا اور مسافروں کا ہے۔‘‘ ۳۔ معلوم ہوا میدان جہاد میں سوار کو مال غنیمت سے تین حصے ملیں گے ایک حصہ اس کا اپنا اور دو حصے اس کی سواری کے۔ ۴۔ میدان جہاد میں چلنے والے پیدل کی نسبت عموماً سوار کی کارکردگی زیادہ ہوتی ہے اس لیے سوار کو اس کی سواری کا بھی حصہ دیا گیا ہے۔ ۵۔ مال غنیمت سے طاقتور، کمزور لڑنے والے اور نہ لڑنے والے سب شرکاء کو برابر حصہ ملے گا۔ عبداللہ بن عباس رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے میدان بدر کے شرکاء میں مال غنیمت کو برابر برابر تقسیم فرمایا۔ (سنن ابو داود، رقم: ۲۷۳۹)"}]])